/* Données du cours AE07 : figures SVG, chapitres (L), zones (Z), laboratoires (LAB). Extrait de mesure-quest.html. */
/* ===================== FIGURES SVG ===================== */
const F={};
F.wave=(type,opts={})=>{const W=600,H=200,m=H/2,A=70;let d='';const n=300;const f=t=>{const p=(t*2)%1;switch(type){case'sin':return Math.sin(t*4*Math.PI);case'sq':return p<.5?1:-1;case'tri':return 4*Math.abs(p-.5)-1;case'rect':return Math.abs(Math.sin(t*4*Math.PI));case'dc':return .5+.5*Math.sin(t*4*Math.PI);case'pulse':return p<.5?1:0;case'harm':return Math.sin(t*4*Math.PI)+(opts.h3||0)*Math.sin(t*12*Math.PI)+(opts.h5||0)*Math.sin(t*20*Math.PI)}};for(let i=0;i<=n;i++){const t=i/n,y=m-A*f(t);d+=(i?'L':'M')+(t*W).toFixed(1)+' '+y.toFixed(1)+' '}
const avg=opts.avg!=null?`<line x1="0" x2="${W}" y1="${m-A*opts.avg}" y2="${m-A*opts.avg}" stroke="#5BD98A" stroke-dasharray="6 4"/><text x="${W-4}" y="${m-A*opts.avg-6}" fill="#5BD98A" text-anchor="end" font-size="12" font-family="IBM Plex Mono">moyenne</text>`:'';
const rms=opts.rms!=null?`<line x1="0" x2="${W}" y1="${m-A*opts.rms}" y2="${m-A*opts.rms}" stroke="#FFB347" stroke-dasharray="6 4"/><text x="${W-4}" y="${m-A*opts.rms-6}" fill="#FFB347" text-anchor="end" font-size="12" font-family="IBM Plex Mono">efficace</text>`:'';
return `<svg viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="#0a0f1a"/>${[0,1,2,3,4].map(i=>`<line x1="0" x2="${W}" y1="${i*50}" y2="${i*50}" stroke="#1c2740"/>`).join('')}<line x1="0" x2="${W}" y1="${m}" y2="${m}" stroke="#3a4a6a"/><path d="${d}" fill="none" stroke="#4FD1E8" stroke-width="2.5"/>${avg}${rms}</svg>`};
F.dial=(val,label)=>{const a=-140+280*val,r=(a-90)*Math.PI/180;return `<svg viewBox="0 0 300 190"><rect width="300" height="190" fill="#0a0f1a"/><path d="M40 160 A120 120 0 1 1 260 160" fill="none" stroke="#26334F" stroke-width="10"/>${Array.from({length:11},(_,i)=>{const t=(-140+28*i-90)*Math.PI/180;return `<line x1="${150+105*Math.cos(t)}" y1="${160+105*Math.sin(t)}" x2="${150+125*Math.cos(t)}" y2="${160+125*Math.sin(t)}" stroke="#8A98B4" stroke-width="2"/>`}).join('')}<line x1="150" y1="160" x2="${150+118*Math.cos(r)}" y2="${160+118*Math.sin(r)}" stroke="#FFB347" stroke-width="3"/><circle cx="150" cy="160" r="8" fill="#FFB347"/><text x="150" y="185" text-anchor="middle" fill="#8A98B4" font-size="12" font-family="IBM Plex Mono">${label||''}</text></svg>`};
const T=(x,y,s,c='#E6EDF7',a='middle')=>`<text x="${x}" y="${y}" fill="${c}" font-size="13" font-family="IBM Plex Mono" text-anchor="${a}">${s}</text>`;
F.circuit=kind=>{const src=`<circle cx="60" cy="100" r="18" fill="none" stroke="#E6EDF7" stroke-width="2"/>${T(60,105,'U')}`;const R=(x,y,l)=>`<rect x="${x-14}" y="${y-30}" width="28" height="60" fill="none" stroke="#E6EDF7" stroke-width="2"/>${T(x,y+50,l)}`;const M=(x,y,l,c)=>`<circle cx="${x}" cy="${y}" r="20" fill="#131C2E" stroke="${c}" stroke-width="2.5"/>${T(x,y+5,l,c)}`;
if(kind==='amp')return `<svg viewBox="0 0 420 200">${src}<path d="M60 82 V40 H330 V70 M330 130 V160 H60 V118" fill="none" stroke="#E6EDF7" stroke-width="2"/>${R(330,100,'R')}${M(200,40,'A','#FFB347')}${T(200,80,'en série, Ri très faible','#FFB347')}</svg>`;
if(kind==='volt')return `<svg viewBox="0 0 420 200">${src}<path d="M60 82 V40 H330 V70 M330 130 V160 H60 V118 M260 40 V60 M260 140 V160" fill="none" stroke="#E6EDF7" stroke-width="2"/>${R(330,100,'R')}${M(260,100,'V','#4FD1E8')}${T(150,120,'en parallèle, Ri très élevée','#4FD1E8')}</svg>`;
if(kind==='shunt')return `<svg viewBox="0 0 420 200">${T(40,105,'I →','#FFB347','start')}<path d="M90 100 H150 M250 100 H330 M170 100 V60 H230 V100 M170 100 V140 H230 V100" fill="none" stroke="#E6EDF7" stroke-width="2"/><rect x="150" y="88" width="100" height="24" fill="none" stroke="#FFB347" stroke-width="2.5"/>${T(200,80,'Rs = 0,001 Ω','#FFB347')}${M(200,40,'V','#4FD1E8')}${T(200,180,'I = Um / Rs')}</svg>`;
if(kind==='ti')return `<svg viewBox="0 0 420 200"><path d="M20 100 H160" stroke="#FFB347" stroke-width="6"/>${T(90,85,'I1 = 400 A','#FFB347')}<circle cx="200" cy="100" r="45" fill="none" stroke="#8A98B4" stroke-width="14"/><path d="M200 55 V20 H340 V80 M200 145 V180 H340 V120" fill="none" stroke="#4FD1E8" stroke-width="2"/>${M(340,100,'A','#4FD1E8')}${T(270,15,'I2 = 5 A','#4FD1E8')}${T(200,105,'w2')}${T(340,195,'secondaire TOUJOURS fermé','#FF6B6B')}</svg>`;
if(kind==='bridge')return `<svg viewBox="0 0 420 220"><path d="M210 20 L60 110 L210 200 L360 110 Z M60 110 H360" fill="none" stroke="#E6EDF7" stroke-width="2"/>${T(120,60,'Rx')}${T(300,60,'R2')}${T(120,170,'R3 (réglable)')}${T(300,170,'R4')}${M(210,110,'0','#5BD98A')}${T(210,215,'équilibré : Rx / R2 = R3 / R4','#FFB347')}</svg>`;
if(kind==='rcd')return `<svg viewBox="0 0 420 200"><path d="M20 80 H400 M20 120 H400" stroke="#E6EDF7" stroke-width="2"/><circle cx="200" cy="100" r="45" fill="none" stroke="#8A98B4" stroke-width="12"/>${T(40,70,'L →','#FFB347','start')}${T(40,140,'← N','#4FD1E8','start')}<path d="M245 100 H300 V40" fill="none" stroke="#5BD98A" stroke-width="2"/><rect x="280" y="20" width="40" height="20" fill="#131C2E" stroke="#5BD98A"/>${T(300,34,'relais','#5BD98A')}${T(200,185,'IL = IN → flux nul → rien. IL ≠ IN → déclenchement','#8A98B4')}</svg>`;
if(kind==='tdr')return `<svg viewBox="0 0 600 200"><rect width="600" height="200" fill="#0a0f1a"/><path d="M20 100 H60 L70 40 L80 100 H300 L310 150 L320 100 H580" fill="none" stroke="#4FD1E8" stroke-width="2.5"/>${T(70,30,'impulsion émise','#4FD1E8')}${T(310,175,'écho du défaut (court-circuit)','#FFB347')}<line x1="70" x2="310" y1="120" y2="120" stroke="#FFB347" stroke-dasharray="4 4"/>${T(190,135,'temps → distance','#FFB347')}</svg>`;
if(kind==='depth')return `<svg viewBox="0 0 420 220"><rect y="120" width="420" height="100" fill="#1a2238"/><circle cx="210" cy="180" r="10" fill="#FFB347"/>${T(210,200,'câble','#FFB347')}<line x1="210" y1="115" x2="210" y2="60" stroke="#4FD1E8" stroke-width="4"/>${T(210,50,'A : bobine verticale, minimum','#4FD1E8')}<line x1="270" y1="115" x2="310" y2="75" stroke="#5BD98A" stroke-width="4"/>${T(330,70,'B : 45°, 2e minimum','#5BD98A')}<path d="M210 130 H270" stroke="#E6EDF7" stroke-dasharray="4 3"/>${T(240,145,'x1 = profondeur t')}</svg>`;
if(kind==='phasor')return `<svg viewBox="0 0 420 220"><g transform="translate(120,110)">${[0,120,240].map((a,i)=>{const r=(a-90)*Math.PI/180;return `<line x1="0" y1="0" x2="${80*Math.cos(r)}" y2="${80*Math.sin(r)}" stroke="#FFB347" stroke-width="3"/>${T(95*Math.cos(r),95*Math.sin(r)+4,'L'+(i+1),'#FFB347')}`}).join('')}</g><g transform="translate(310,110)">${[30,150,270].map((a,i)=>{const r=(a-90)*Math.PI/180;return `<line x1="0" y1="0" x2="${80*Math.cos(r)}" y2="${80*Math.sin(r)}" stroke="#4FD1E8" stroke-width="3"/>${T(95*Math.cos(r),95*Math.sin(r)+4,'L'+(i+1)+"'",'#4FD1E8')}`}).join('')}</g>${T(120,210,'réseau 1')}${T(310,210,'réseau 2, déphasé de 30° : Ud ≠ 0','#4FD1E8')}</svg>`;
if(kind==='tn')return `<svg viewBox="0 0 600 220"><rect width="600" height="220" fill="#0a0f1a"/>${T(80,25,'TN-C','#FFB347')}<path d="M20 60 H260 M20 90 H260 M20 120 H260 M20 150 H260" stroke="#E6EDF7" stroke-width="2"/>${T(240,145,'PEN','#5BD98A','end')}<path d="M100 150 V190 M180 150 V190" stroke="#5BD98A" stroke-width="2"/>${T(100,205,'⏚')}${T(180,205,'⏚')}${T(140,180,'PEN mis à la terre plusieurs fois','#8A98B4')}${T(400,25,'TN-S','#4FD1E8')}<path d="M320 60 H580 M320 90 H580 M320 120 H580 M320 150 H420 M420 150 H580 M420 150 V175 H580" stroke="#E6EDF7" stroke-width="2"/>${T(560,145,'N','#4FD1E8','end')}${T(560,170,'PE','#5BD98A','end')}<path d="M420 175 V195" stroke="#5BD98A" stroke-width="2"/>${T(420,210,'⏚ un seul point')}</svg>`;
return ''};

/* ===================== DONNÉES DU COURS ===================== */
const Z=[{n:'Zone 1 · Le laboratoire',l:[1,2,3]},{n:'Zone 2 · La cabine de distribution',l:[4,5,6,7]},{n:'Zone 3 · Le réseau sous tension',l:[8,9]},{n:'Zone 4 · Les câbles',l:[10,11,12,13]},{n:'Zone 5 · Boss final',l:[14]}];
const L=[];
/* -------- 1 -------- */
L[1]={t:'Principes généraux',s:'Mesurer, c\'est comparer. Vocabulaire, erreurs, étalonnage.',b:[
{h:'Mesurer, c\'est comparer',p:['On compare une grandeur inconnue à une grandeur de référence. Le résultat est une <b>valeur mesurée</b> : un nombre multiplié par une unité (3 volts).','Une bonne mesure est <b>objective</b> (indépendante des sens humains), <b>reproductible</b> (on peut la refaire et la contrôler) et <b>quantitative</b> (pourvue d\'un nombre).'],k:'Mesurer n\'est pas estimer. Estimer, c\'est subjectif et peu reproductible.'},
{h:'Vraie, mesurée, erreur',p:['Le <b>mesurande</b> est la grandeur qu\'on veut connaître. La <b>valeur vraie</b> existe mais reste inatteignable. On la remplace par une <b>valeur conventionnelle</b>.','<b>Erreur de mesure e = valeur mesurée − valeur vraie</b>. Exemple : on lit 1,253 V pour une valeur conventionnelle de 1,270 V. e = −0,017 V.'],k:'L\'erreur absolue garde l\'unité (V, A). L\'erreur relative est un pourcentage, sans unité.',fig:F.dial(.62,'valeur mesurée 1,253 V')},
{h:'Les 4 opérations métrologiques',p:['<b>Contrôler</b> : décider si une condition est remplie (dans la tolérance ou non).','<b>Étalonner</b> : déterminer l\'erreur de mesure en comparant à une référence. <b>Aucune intervention</b> sur l\'appareil : il ressort dans le même état.','<b>Ajuster (régler)</b> : intervenir sur l\'appareil pour réduire l\'erreur.','<b>Vérifier</b> : opération <b>officielle</b> par une autorité, obligatoire pour les instruments du commerce (compteurs d\'électricité, balances, compteurs de gaz).'],k:'Étalonnage = on regarde. Ajustage = on touche. Vérification = l\'État tamponne.'},
{h:'Erreurs systématiques et aléatoires',p:['<b>Systématique</b> : effet connu, qui se répète à l\'identique (influence de la température sur l\'appareil). On ne peut <b>pas la détecter en répétant la mesure</b> dans les mêmes conditions.','<b>Aléatoire</b> : influences imprévisibles (contact des pinces, pression du ressort). Elle se décrit par une courbe de Gauss. Sur des mesures de courant de court-circuit, environ <b>80 %</b> seulement sont utilisables.'],k:'Répéter la mesure réduit l\'aléatoire, jamais le systématique.'},
{h:'Normes et marquage CE',p:['Ceux qui <b>édictent</b> les normes : ISO, CEI (IEC), CENELEC, DIN, IEEE, ANSI, ETSI.','Ceux qui <b>contrôlent</b> la conformité : ASE (Suisse), UL, CSA, TÜV, GS.','Le fabricant établit lui-même la déclaration CE et appose le marquage. La liste de normes imprimée sur un appareil <b>ne fait pas foi</b> : seul un organisme de contrôle le confirme.'],k:'Instruments : voltmètre, ampèremètre, mégohmmètre (isolement), tellurohmmètre (prise de terre), phasemètre (cos φ), luxmètre (éclairement).'}],
q:[
{t:'qcm',q:'Un voltmètre affiche 1,253 V. La valeur conventionnelle est 1,270 V. Quelle est l\'erreur de mesure ?',c:['+0,017 V','−0,017 V','1,3 %','0 V, la mesure est juste'],a:1,e:'e = mesurée − vraie = 1,253 − 1,270 = −0,017 V. Le signe compte.'},
{t:'qcm',q:'Lors d\'un étalonnage, que fait-on à l\'appareil ?',c:['On le règle jusqu\'à ce qu\'il affiche juste','Rien : on détermine seulement son erreur','On le fait vérifier officiellement','On remplace son fusible'],a:1,e:'L\'étalonnage détermine l\'erreur sans intervention. Le réglage, c\'est l\'ajustage.'},
{t:'vf',q:'Une erreur systématique peut être détectée en répétant plusieurs fois la mesure dans les mêmes conditions.',a:false,e:'Faux. Elle se reproduit à l\'identique à chaque fois, donc la répétition ne la révèle pas.'},
{t:'match',q:'Associe chaque opération à sa définition.',p:[['Contrôler','Décider si une condition est remplie'],['Étalonner','Déterminer l\'erreur sans intervenir'],['Ajuster','Intervenir pour réduire l\'erreur'],['Vérifier','Opération officielle par une autorité']],e:'Les quatre opérations métrologiques du chapitre 1.5.'},
{t:'qcm',q:'Quel instrument mesure la résistance d\'une prise de terre ?',c:['Mégohmmètre','Tellurohmmètre','Phasemètre','Galvanomètre'],a:1,e:'Tellurohmmètre pour la terre (Ω). Le mégohmmètre mesure l\'isolement (MΩ).'},
{t:'qcm',q:'Lequel de ces organismes est un organisme de contrôle, et non un institut qui édicte des normes ?',c:['CEI','CENELEC','TÜV','ISO'],a:2,e:'TÜV, ASE, UL, CSA contrôlent. CEI, ISO, CENELEC, DIN édictent.'},
{t:'vf',q:'La liste des normes imprimée sur un appareil de mesure suffit à prouver sa conformité.',a:false,e:'Faux. Il faut qu\'un organisme de contrôle confirme que l\'appareil répond aux normes.'},
{t:'qcm',q:'Quelle proportion de mesures de courant de court-circuit donne un résultat utilisable, selon le cours ?',c:['100 %','95 %','80 %','50 %'],a:2,e:'Environ 80 %. Les 20 % restants sont écartés à cause des erreurs aléatoires.'},
{t:'qcm',q:'« Objective » signifie que la mesure est…',c:['indépendante des organes sensoriels humains','réalisée avec un appareil numérique','exprimée en pourcentage','faite par deux personnes'],a:0,e:'Objective : indépendante des sens de l\'être humain. Reproductible : réitérable. Quantitative : avec un nombre.'}]};
/* -------- 2 -------- */
L[2]={t:'Appareils de mesure',s:'Cadre mobile, ferromagnétique, CAT, échantillonnage, bits, digits.',b:[
{h:'Appareil à cadre mobile',p:['Une bobine mobile dans le champ d\'un <b>aimant permanent</b>. Le courant crée une <b>force de Lorentz</b> qui fait tourner la bobine contre un ressort. L\'aiguille indique la valeur.','<b>Avantages</b> : grande précision, faible consommation, insensible aux champs extérieurs. <b>Inconvénients</b> : bobine mobile fragile, dépend de la position, sensible aux surcharges.'],k:'Le cadre mobile indique la <b>valeur moyenne</b>. Sur une grandeur purement alternative, il affiche zéro.',fig:F.dial(.45,'cadre mobile')},
{h:'Appareil ferromagnétique et les autres',p:['<b>Ferromagnétique (électromagnétique)</b> : bobine fixe, palette de fer mobile. Mesure le continu et l\'alternatif, affiche la <b>valeur efficace de n\'importe quelle forme d\'onde</b>. Solide, supporte les surcharges. Mais peu sensible, consommation élevée, sensible aux champs extérieurs.','<b>Électrodynamique</b> : deux bobines, c\'est un multiplicateur. Idéal pour la <b>puissance active</b> (wattmètre).','<b>Thermique</b> : dilatation d\'un conducteur chauffé, valeur efficace.','<b>Électrostatique</b> : force de Coulomb entre plaques, très grande résistance interne, haute tension.'],k:'Ferro = TRMS mécanique. Électrodynamique = wattmètre.'},
{h:'Sécurité et catégories de mesure',p:['Un multimètre est protégé par des <b>fusibles haute performance (HPC)</b>, par exemple contre un branchement en parallèle en mode ampèremètre.','<b>CAT I</b> : circuits non reliés au réseau (batteries, électronique).<br><b>CAT II</b> : prises monophasées (ménages, bureaux).<br><b>CAT III</b> : distribution triphasée de bâtiment, consommateurs stationnaires.<br><b>CAT IV</b> : source de l\'installation BT, compteurs, raccordement principal, réseau de distribution.'],k:'Le spécialiste de réseau travaille en CAT IV au raccordement et souvent en CAT III ailleurs.'},
{h:'La chaîne numérique',p:['<b>Transducteur → TAS → CAN → TNS → µP → affichage</b>.','Transducteur : convertit la grandeur en signal électrique (thermistor, capteur à effet Hall, photodiode). TAS : traitement analogique (amplification, filtrage). CAN : convertisseur analogique numérique. TNS (DSP) : traitement numérique.','<b>Échantillonnage</b> : fa = 2 × fmax. Pour les mesures à 50 Hz on échantillonne aujourd\'hui de 10 à 50 kHz.','<b>Quantification</b> : P = 2^N points. 8 bits = 256, 16 bits = 65 536. Plus petit pas : Δ = étendue / (2^N − 1).'],k:'Exemple du cours : 16 bits sur 250 V → Δ = 250 / 65 535 = 3,8147 mV.',lab:'quant'},
{h:'Précision et digits',p:['Le fabricant garantit l\'erreur sous la forme <b>± (x % de la valeur mesurée + y digits)</b>, valable dans des conditions de référence : 23 °C ± 2 K, 40 à 60 % d\'humidité, 45 à 65 Hz, signal sinus.','Un <b>digit</b> est le plus petit incrément affichable. Sa valeur dépend du nombre de chiffres et de l\'étendue de mesure. Affichage 19,98 V → 1 digit = 0,01 V.','Chiffres partiels sur les afficheurs : ½ chiffre = 0 ou 1. ¾ chiffre = 0 à 3. Toujours à gauche.'],k:'Plus il y a de chiffres, plus le digit est petit, donc plus la précision est fine.'}],
q:[
{t:'qcm',q:'Quel appareil électromécanique affiche la valeur efficace quelle que soit la forme d\'onde ?',c:['Cadre mobile','Ferromagnétique','Électrostatique','Cadre mobile avec redresseur'],a:1,e:'Le ferromagnétique est un TRMS mécanique. Le cadre mobile donne la valeur moyenne.'},
{t:'qcm',q:'Mesure sur le compteur et le raccordement principal d\'un immeuble : quelle catégorie ?',c:['CAT I','CAT II','CAT III','CAT IV'],a:3,e:'CAT IV : source de l\'installation BT et réseaux de distribution.'},
{t:'num',q:'Un appareil 8 bits mesure sur une étendue de 100 V. Quel est le plus petit pas (Δ) en volts ?',a:0.392,tol:3,u:'V',e:'Δ = 100 / (2^8 − 1) = 100 / 255 = 0,392 V.'},
{t:'num',q:'Combien de points de quantification offre un convertisseur 16 bits ?',a:65536,tol:0,u:'points',e:'P = 2^16 = 65 536.'},
{t:'qcm',q:'Fréquence d\'échantillonnage minimale pour un signal dont la fréquence maximale est 2 kHz ?',c:['1 kHz','2 kHz','4 kHz','50 kHz'],a:2,e:'fa = 2 × fmax = 4 kHz.'},
{t:'order',q:'Remets dans l\'ordre la chaîne d\'un système de mesure numérique.',i:['Transducteur','Traitement analogique (TAS)','Convertisseur AN (CAN)','Traitement numérique (TNS)','Microprocesseur','Affichage'],e:'Transducteur → TAS → CAN → TNS → µP → affichage.'},
{t:'qcm',q:'Un afficheur indique 19,98 V. Que vaut 1 digit ?',c:['1 V','0,1 V','0,01 V','0,001 V'],a:2,e:'Le plus petit incrément est 0,01 V.'},
{t:'qcm',q:'La force qui fait tourner la bobine d\'un appareil à cadre mobile s\'appelle…',c:['force de Coulomb','force de Lorentz','force de Foucault','force magnétomotrice'],a:1,e:'Force de Lorentz : courant dans un champ magnétique.'},
{t:'vf',q:'Un ½ chiffre sur un afficheur peut représenter les chiffres 0 à 4.',a:false,e:'Faux. ½ chiffre : 0 ou 1. ¾ chiffre : 0 à 3.'},
{t:'qcm',q:'Quel appareil est un multiplicateur adapté à la mesure de la puissance active ?',c:['Thermique','Électrodynamique','Cadre mobile','Électrostatique'],a:1,e:'La déviation est proportionnelle au produit des deux courants : wattmètre.'}]};
/* -------- 3 -------- */
L[3]={t:'Courant alternatif',s:'Moyenne, redressée, efficace. RMS, TRMS, facteurs de forme et de crête.',b:[
{h:'Trois valeurs pour un signal',p:['<b>Valeur moyenne</b> : la composante continue. Les surfaces sous l\'axe comptent en négatif. Pour une grandeur purement alternative, elle vaut <b>zéro</b>.','<b>Valeur redressée</b> : moyenne du signal redressé (toutes les surfaces positives). Toujours > 0 pour une grandeur alternative.','<b>Valeur efficace</b> : la valeur continue qui produirait <b>la même énergie</b> dans une résistance. 0,5 A efficace dans 1 Ω = 0,25 W, que ce soit du continu ou de l\'alternatif.'],k:'Pour un sinus : Ueff = Ucrête / √2. 325 V crête → 230 V efficace.',fig:F.wave('sin',{avg:0,rms:.707})},
{h:'Laboratoire des formes d\'onde',p:['Change la forme d\'onde et regarde comment bougent la moyenne, la redressée et l\'efficace. Le facteur de forme kf = efficace / redressée. Le facteur de crête ks = crête / efficace.'],lab:'rms'},
{h:'RMS, TRMS, et le piège du redresseur',p:['<b>Non RMS</b> : appareil qui mesure la redressée puis multiplie par le facteur de forme du sinus (kf = 1,11). <b>Juste uniquement si le signal est sinusoïdal.</b> C\'est le cas du cadre mobile avec redresseur et des multimètres simples.','<b>RMS</b> : valeur efficace de n\'importe quelle forme d\'onde symétrique.','<b>TRMS (true RMS)</b> : valeur efficace totale, forme quelconque, non symétrique, AC + DC.'],k:'Électronique de puissance, variateurs, LED : signaux non sinusoïdaux. Il faut un TRMS.'},
{h:'Exemple du cours : tension carrée pulsée',p:['Une tension de 2 V pendant une demi-période, 0 V pendant l\'autre (période 2 s). Surface des carrés : 2² × 1 s = 4 V²s. Divisé par T = 2 s : 2 V². Racine : <b>Ueff = 1,414 V</b>.','La valeur moyenne serait 1 V. Un appareil non RMS aurait affiché n\'importe quoi.'],fig:F.wave('pulse',{avg:.5,rms:.707})}],
q:[
{t:'qcm',q:'Valeur moyenne d\'une tension purement alternative sinusoïdale ?',c:['Ucrête / √2','Ucrête × 0,637','0','Ucrête'],a:2,e:'Les surfaces positives et négatives s\'annulent : moyenne nulle.'},
{t:'num',q:'Un sinus a une valeur de crête de 325 V. Valeur efficace en volts ?',a:230,tol:2,u:'V',e:'325 / √2 = 229,8 V ≈ 230 V.'},
{t:'qcm',q:'Le facteur de forme kf est le rapport…',c:['crête / efficace','efficace / redressée','moyenne / efficace','redressée / crête'],a:1,e:'kf = X efficace / x redressée. Pour le sinus : 1,11.'},
{t:'qcm',q:'Facteur de crête d\'un sinus ?',c:['1,11','1,414','2','0,707'],a:1,e:'ks = crête / efficace = √2 = 1,414.'},
{t:'qcm',q:'Quel appareil affiche une valeur fausse sur un courant de variateur (non sinusoïdal) ?',c:['Ferromagnétique','Multimètre TRMS','Cadre mobile avec redresseur','Appareil thermique'],a:2,e:'Le cadre mobile avec redresseur suppose un sinus (kf 1,11). Les autres mesurent l\'efficace réelle.'},
{t:'vf',q:'TRMS signifie que l\'appareil mesure la valeur efficace totale, composante continue comprise.',a:true,e:'Vrai. True RMS : forme quelconque, non symétrique, AC + DC.'},
{t:'num',q:'Tension carrée : 4 V pendant une demi-période, 0 V pendant l\'autre. Valeur efficace en volts ?',a:2.83,tol:3,u:'V',e:'√((4² × T/2) / T) = √8 = 2,83 V.'},
{t:'qcm',q:'La valeur efficace correspond à la valeur continue qui…',c:['a la même crête','a la même surface sur une période','produit la même dépense d\'énergie','a la même fréquence'],a:2,e:'Même énergie dissipée dans une résistance. C\'est la définition.'}]};
/* -------- 4 -------- */
L[4]={t:'Champ tournant et phases',s:'Sens de rotation, détection de tension, comparaison des phases avant de coupler deux réseaux.',b:[
{h:'Le réseau triphasé',p:['Trois enroulements décalés de 120°. À <b>3000 tr/min</b>, les tensions ont une fréquence de <b>50 Hz</b>. Seul le triphasé produit un champ tournant à densité de flux constante.','Dénominations des phases : <b>L1 L2 L3 = R S T = U V W</b>. Couleurs : marron, noir, gris.'],k:'Les tâches de routine du spécialiste : sens de rotation, détection de tension, concordance des phases.'},
{h:'Trois paramètres à comparer',p:['Avant d\'interconnecter deux réseaux, trois choses doivent coïncider : <b>l\'emplacement des phases, la tension et la fréquence</b>.','Même fréquence, même phase, amplitude différente → tension différentielle → courant de compensation.','Même fréquence et amplitude, mais déphasage → tension différentielle Ud à la fréquence du réseau.','Déphasage de 120° (phases inversées) : Ud vaut la <b>tension composée</b>. On peut parfois résoudre par croisement.'],fig:F.circuit('phasor')},
{h:'Procédure de comparaison BT',p:['Avec un voltmètre, on mesure la tension différentielle.','<b>1. Séparément de chaque côté</b> (détection de tension) : L1, L2, L3 contre PEN, puis L1 L2, L1 L3, L2 L3. Si les valeurs sont normales, on continue.','<b>2. Entre les deux réseaux</b> : L1 à L1\', L1 à L2\', L1 à L3\', et ainsi de suite, plus PEN à PEN\'.','Pour coupler, la tension différentielle entre conducteurs associés doit être <b>aussi proche de zéro que possible</b>. Des différences de charge et de longueur de ligne créent toujours un petit écart : l\'appréciation revient au spécialiste.'],k:'D\'abord chaque côté seul, ensuite entre les deux. Jamais l\'inverse.'}],
q:[
{t:'qcm',q:'Quels sont les trois paramètres à vérifier avant d\'interconnecter deux réseaux ?',c:['Tension, courant, puissance','Emplacement des phases, tension, fréquence','Fréquence, cos φ, THD','Tension, isolement, terre'],a:1,e:'Phase, tension, fréquence.'},
{t:'qcm',q:'À quelle vitesse tourne l\'alternateur pour obtenir 50 Hz avec une paire de pôles ?',c:['1500 tr/min','3000 tr/min','50 tr/min','6000 tr/min'],a:1,e:'3000 tr/min = 50 tours par seconde = 50 Hz.'},
{t:'qcm',q:'Deux réseaux de même fréquence et même amplitude, mais déphasés de 120° entre L1 et L1\'. Que mesure le voltmètre ?',c:['0 V','La tension simple (230 V)','La tension composée (400 V)','La moitié de la tension simple'],a:2,e:'Avec 120° de décalage, la tension différentielle vaut la tension composée.'},
{t:'order',q:'Ordre correct des mesures pour une comparaison de phases en BT.',i:['Mesurer L1, L2, L3 contre PEN de chaque côté séparément','Mesurer L1 L2, L1 L3, L2 L3 de chaque côté','Mesurer entre les deux réseaux : L1 à L1\', L1 à L2\', etc.','Mesurer PEN à PEN\'','Décider de l\'interconnexion'],e:'D\'abord chaque côté seul, puis entre les deux réseaux.'},
{t:'vf',q:'La dénomination R S T correspond à L1 L2 L3.',a:true,e:'Vrai. L1 L2 L3 = R S T = U V W.'},
{t:'qcm',q:'Même phase, même fréquence, mais amplitude plus petite d\'un côté. Conséquence si on couple ?',c:['Rien, c\'est acceptable','Un courant de compensation circule','Le disjoncteur différentiel déclenche','La fréquence change'],a:1,e:'La tension différentielle fait circuler un courant de compensation du réseau 1 vers le réseau A.'}]};
/* -------- 5 -------- */
L[5]={t:'Mesurer I et U',s:'Ampèremètre en série, voltmètre en parallèle, shunt, extension d\'étendue.',b:[
{h:'L\'ampèremètre : en série',p:['L\'ampèremètre s\'insère <b>en série</b> avec le consommateur. Sa résistance interne (0,01 à 2 Ω) s\'ajoute au circuit et modifie le courant : I2 = U / (Ri + R + Rm).','Si Rm ≪ Ri + R, on néglige l\'erreur. Sinon on corrige.','Les multimètres du marché mesurent en direct jusqu\'à <b>20 A</b> (attention à la durée maximale).'],k:'Plages typiques : 4 à 20 mA (transducteurs), 0 à 1 A (secondaire HT/MT), 0 à 5 A (secondaire MT/BT), 0 à 200 A CC (batteries).',fig:F.circuit('amp')},
{h:'Le voltmètre : en parallèle',p:['Le voltmètre se branche <b>en parallèle</b> sur la résistance. Son impédance doit être de plusieurs kΩ, mieux <b>MΩ</b>, pour ne pas charger le circuit.'],k:'Au quotidien, l\'erreur due à la consommation propre du voltmètre est ignorée.',fig:F.circuit('volt')},
{h:'Le shunt',p:['Pour les grands courants, on fait passer I dans une résistance connue Rs (0,01 ou <b>0,001 Ω</b>) et on mesure la chute de tension : <b>I = Um / Rs</b>.','Les résistances de contact faussent la mesure. Solution : le <b>shunt à quatre fils</b>, avec contacts de tension séparés des raccordements de puissance.'],fig:F.circuit('shunt')},
{h:'Étendre l\'étendue de mesure',p:['<b>Courant</b> : résistances parallèles. Le montage où la répartition du courant ne dépend pas des résistances de contact de l\'interrupteur est préférable.','<b>Tension</b> : résistance série Rv. <b>Rv = Rm × (U − Umax) / Umax</b>. Doubler l\'étendue double la résistance d\'entrée. C\'est pourquoi on indique la résistance d\'entrée en <b>kΩ/V</b> (Ri/U).'],k:'Exemple : Rm = 10 kΩ, pleine déviation 10 V, on veut 100 V → Rv = 10 kΩ × 90/10 = 90 kΩ.'}],
q:[
{t:'qcm',q:'Comment se branche un ampèremètre ?',c:['En parallèle avec le consommateur','En série avec le consommateur','Entre L et PE','Sur le secondaire d\'un TP'],a:1,e:'En série. Sa faible résistance s\'ajoute au circuit.'},
{t:'num',q:'Shunt de 0,001 Ω. On mesure 150 mV à ses bornes. Courant en ampères ?',a:150,tol:1,u:'A',e:'I = Um / Rs = 0,150 / 0,001 = 150 A.'},
{t:'num',q:'Voltmètre Rm = 10 kΩ, pleine déviation à 10 V. Résistance série Rv pour lire jusqu\'à 100 V, en kΩ ?',a:90,tol:1,u:'kΩ',e:'Rv = Rm × (U − Umax)/Umax = 10 × 90/10 = 90 kΩ.'},
{t:'qcm',q:'Pourquoi un shunt à quatre fils ?',c:['Pour mesurer quatre courants','Pour éliminer l\'influence des résistances de contact','Pour doubler la sensibilité','Pour la séparation galvanique'],a:1,e:'Les contacts de tension séparés ne voient pas les chutes de tension dans les raccords de puissance.'},
{t:'qcm',q:'Impédance souhaitable d\'un voltmètre ?',c:['0,01 Ω','Quelques ohms','Plusieurs kΩ, mieux MΩ','Exactement égale à R'],a:2,e:'Haute impédance pour ne pas charger le circuit.'},
{t:'vf',q:'Brancher un multimètre en mode ampèremètre en parallèle sur la source fait sauter son fusible HPC.',a:true,e:'Vrai. C\'est un court-circuit sur l\'appareil, le fusible HPC le protège.'},
{t:'qcm',q:'Courant maximal typique en mesure directe sur un multimètre du marché ?',c:['2 A','20 A','200 A','1000 A'],a:1,e:'20 A, en respectant la durée maximale autorisée.'},
{t:'qcm',q:'Un voltmètre indique « 20 kΩ/V ». Sur l\'étendue 100 V, sa résistance d\'entrée vaut…',c:['20 kΩ','200 kΩ','2 MΩ','20 MΩ'],a:2,e:'20 kΩ/V × 100 V = 2 MΩ.'}]};
/* -------- 6 -------- */
L[6]={t:'Transformateurs de mesure',s:'TI toujours en court-circuit, TP protégé des courts-circuits. Pinces, Rogowski, Aron.',b:[
{h:'Le transformateur d\'intensité (TI)',p:['Il traduit un grand courant primaire en un petit courant secondaire normalisé : <b>1 A ou 5 A</b>. Séparation galvanique, secondaire mis à la terre.','C\'est un transformateur <b>en court-circuit</b> : K = I1/I2 = w2/w1.','Si on <b>ouvre le secondaire</b> en charge, la force magnétomotrice secondaire disparaît, le noyau sature, des <b>tensions élevées</b> apparaissent : danger et destruction.'],k:'<b>Jamais de fusible</b> dans le secondaire d\'un TI. Les noyaux non utilisés sont court-circuités.',fig:F.circuit('ti')},
{h:'Charge et puissance du TI',p:['La résistance de charge Rb (lignes + entrées d\'appareils) doit correspondre à la puissance assignée en VA : <b>S = I² × Rb</b>.','Trop de charge → saturation avant le courant nominal. Trop peu → inexactitudes.','Exemple : 10 m de 2,5 mm² → Rb = 0,07 Ω → 1,75 VA à 5 A, seulement 0,07 VA à 1 A.'],k:'Les TI pour le décompte (facturation) sont vérifiés officiellement une seule fois et marqués.',lab:'ti'},
{h:'Pinces et Rogowski',p:['<b>Pince ampèremétrique</b> : un TI ouvrable, pas besoin de couper le circuit. Plusieurs conducteurs dans la pince → on mesure la <b>somme des courants</b> (principe de la pince de courant de fuite).','<b>Pince I/U</b> : une résistance au secondaire transforme le courant en tension proportionnelle, pour les analyseurs.','<b>Bobine de Rogowski</b> : <b>sans noyau de fer</b>, donc très linéaire même à fort courant, souple pour les grands faisceaux et jeux de barres, excellente pour les harmoniques.']},
{h:'Le transformateur de potentiel (TP)',p:['Utilisé au-dessus de 600 V environ. Transformateur <b>à vide</b> : Ku = U1/U2 = w1/w2. Secondaires normalisés : <b>100, 110 ou 200 V</b>.','Un court-circuit au secondaire le détruit thermiquement : le secondaire est mis à la terre et <b>protégé par des fusibles</b>.','TP unipolaires en étoile, neutres à la terre : détectent les dissymétries (défaut à la terre). Rapport noté 16 kV/√3 ÷ 100 V/√3 = <b>160</b>.','<b>Circuit d\'Aron</b> : 2 TP bipolaires + 2 TI suffisent pour P et Q quand le neutre n\'est pas distribué.'],k:'TI = source de courant, secondaire fermé. TP = source de tension, secondaire protégé.'}],
q:[
{t:'qcm',q:'Que se passe-t-il si on ouvre le secondaire d\'un TI en service ?',c:['Rien, le courant primaire s\'arrête','Le noyau sature et des tensions élevées apparaissent','Le fusible secondaire saute','Le TP se met en court-circuit'],a:1,e:'La force magnétomotrice secondaire manque, saturation, surtension dangereuse.'},
{t:'vf',q:'On protège le secondaire d\'un transformateur d\'intensité avec un fusible.',a:false,e:'Faux. Jamais de fusible sur un TI : s\'il fond, le secondaire s\'ouvre.'},
{t:'num',q:'TI 400/5 A. Le primaire porte 240 A. Courant secondaire en ampères ?',a:3,tol:1,u:'A',e:'240 / (400/5) = 240 / 80 = 3 A.'},
{t:'qcm',q:'Courants secondaires normalisés d\'un TI ?',c:['1 A ou 5 A','10 A ou 20 A','100 mA','1 A ou 10 A'],a:0,e:'1 A ou 5 A.'},
{t:'qcm',q:'Tensions secondaires normalisées d\'un TP ?',c:['24, 48 V','100, 110 ou 200 V','230 V','400 V'],a:1,e:'100, 110 ou 200 V entre conducteurs extérieurs.'},
{t:'num',q:'Ligne secondaire de 20 m en 2,5 mm² (Rb = 0,14 Ω). Puissance requise avec un courant secondaire de 5 A, en VA ?',a:3.5,tol:2,u:'VA',e:'S = I² × Rb = 25 × 0,14 = 3,5 VA.'},
{t:'qcm',q:'Quel capteur n\'a pas de noyau de fer et reste linéaire à très fort courant ?',c:['Pince ampèremétrique','Shunt','Bobine de Rogowski','TI toroïdal'],a:2,e:'La bobine de Rogowski, sans fer, linéaire, idéale pour les harmoniques.'},
{t:'qcm',q:'Trois conducteurs L1, L2, L3 d\'une charge équilibrée passent ensemble dans une pince. Elle affiche…',c:['Trois fois le courant de phase','Le courant d\'une phase','Environ zéro','La tension composée'],a:2,e:'La pince mesure la somme des courants. Somme d\'un système équilibré : zéro. C\'est le principe de la pince de courant de fuite.'},
{t:'qcm',q:'Le circuit d\'Aron permet de mesurer la puissance triphasée avec…',c:['3 TP et 3 TI','2 TP bipolaires et 2 TI','1 TP et 1 TI','3 TI seulement'],a:1,e:'Deux TP bipolaires et deux TI, quand le neutre n\'est pas distribué.'},
{t:'qcm',q:'Un TP de 16 kV/√3 ÷ 100 V/√3 a un rapport de…',c:['16','92','160','1600'],a:2,e:'16 000 / 100 = 160.'}]};
/* -------- 7 -------- */
L[7]={t:'Puissance et énergie',s:'P, Q, S, cos φ, λ. Compteurs Ferraris et électroniques, smart meter, mise en service.',b:[
{h:'Les trois puissances',p:['<b>S = U × I</b> : puissance apparente [VA], jamais de signe.','<b>P = U × I × cos φ</b> : puissance active [W], mesurée avec un appareil électrodynamique (wattmètre) ou un analyseur.','<b>Q = U × I × sin φ</b> : puissance réactive [var], ne transporte pas d\'énergie en moyenne. Avec un wattmètre, on décale la tension de 90° pour la mesurer.','En triphasé, les tensions composées sont <b>√3</b> fois les tensions simples. P totale = P1 + P2 + P3.'],lab:'power'},
{h:'cos φ et facteur de puissance λ',p:['<b>cos φ</b> (facteur de déphasage) = P/S <b>à la fréquence fondamentale</b> seulement.','<b>λ = P/S</b> (power factor, PF) sur l\'oscillation totale : il <b>tient compte des harmoniques</b>.','Sans harmoniques, λ = cos φ. Avec des charges non linéaires, λ < cos φ.'],k:'Pour une charge purement ohmique (φ = 0°) : S = P et Q = 0.'},
{h:'Énergie et compteurs',p:['<b>W = U × I × t</b> [Ws]. L\'énergie est facturée, donc mesurée avec des instruments certifiés selon la loi fédérale sur les mesures (941.20).','<b>Ferraris</b> : disque en aluminium entraîné par les champs des bobines de tension et d\'intensité, freiné par un aimant permanent (frein à courants de Foucault). La constante c [tours/kWh] figure sur la plaque.','<b>P [kW] = n × 3600 / (c × t)</b> avec n tours en t secondes.','<b>Électronique</b> : plus de mécanique. Courant saisi par TI toroïdal, Rogowski, shunt ou effet Hall. Enregistre la puissance moyenne sur <b>15 minutes</b>, mémoires, interfaces de communication.'],k:'Exemple : c = 600 tr/kWh, 10 tours en 60 s → P = 36 000 / 36 000 = 1 kW.'},
{h:'Smart meter (OApEI)',p:['Déploiement de <b>80 % de smart meters d\'ici 2027</b>.','Saisie de l\'énergie active et réactive par <b>15 minutes</b>, conservation <b>60 jours</b> dans le compteur, communication <b>bidirectionnelle</b>, signalement des interruptions et manipulations, séparation communication / mesure, interface client.','Données : utilisables sans accord sous forme pseudonymisée à des fins de réseau et Meter2Cash. Consultées une fois par jour. Supprimées après <b>un an</b> si non pertinentes pour la facturation.','<b>Mesure directe</b> jusqu\'à environ <b>80 A</b>. Au-delà, mesure par transformateurs.']},
{h:'Mise en service et changement de compteur',p:['<b>Mise en service</b> : 1. tous les TI en court-circuit sur la borne d\'essai. 2. tous les TP séparés du secondaire. 3. vérifier le câblage. 4. enclencher le primaire. 5. contrôler à la pince jusqu\'à la borne d\'essai. 6. supprimer les ponts de court-circuit phase par phase. 7. contrôler les tensions. 8. fermer les ponts de tension. 9. vérifier les relevés, comparer avec un second système.','<b>Changement</b> : 1. EPI. 2. mesurer L1 à la pince côté transformateur. 3. court-circuiter sur la borne d\'essai (le courant ne doit pas changer). 4. idem L2, L3. 5. ouvrir le circuit tension. 6. vérifier l\'absence de tension. 7. changer. Puis refermer dans l\'ordre inverse et vérifier.'],k:'Avant de toucher un circuit de courant : court-circuit sur la borne d\'essai, et le courant à la pince ne doit pas bouger.'}],
q:[
{t:'num',q:'U = 230 V, I = 10 A, cos φ = 0,8. Puissance active P en watts ?',a:1840,tol:1,u:'W',e:'P = 230 × 10 × 0,8 = 1840 W.'},
{t:'num',q:'Même charge (230 V, 10 A, cos φ = 0,8). Puissance réactive Q en var ?',a:1380,tol:1,u:'var',e:'sin φ = 0,6. Q = 230 × 10 × 0,6 = 1380 var.'},
{t:'qcm',q:'Quelle grandeur tient compte des harmoniques ?',c:['cos φ','λ (facteur de puissance)','S','Q'],a:1,e:'λ = P/S sur l\'oscillation totale. cos φ ne concerne que la fondamentale.'},
{t:'num',q:'Compteur Ferraris c = 600 tr/kWh. Le disque fait 20 tours en 60 s. Puissance en kW ?',a:2,tol:1,u:'kW',e:'P = n × 3600 / (c × t) = 72 000 / 36 000 = 2 kW.'},
{t:'qcm',q:'Qu\'est-ce qui limite la vitesse du disque d\'un compteur Ferraris ?',c:['Un ressort','Un aimant permanent (frein à courants de Foucault)','La bobine de tension','Un engrenage'],a:1,e:'L\'aimant permanent crée un contre-couple : frein à courants de Foucault.'},
{t:'qcm',q:'Objectif de déploiement des smart meters selon l\'OApEI ?',c:['50 % d\'ici 2025','80 % d\'ici 2027','100 % d\'ici 2030','30 % d\'ici 2027'],a:1,e:'80 % d\'ici 2027.'},
{t:'qcm',q:'Durée minimale de conservation des données dans un smart meter ?',c:['24 h','15 jours','60 jours','1 an'],a:2,e:'Au moins 60 jours dans le compteur, par pas de 15 minutes.'},
{t:'order',q:'Changement d\'un compteur à transformateurs : remets les premières étapes dans l\'ordre.',i:['Mettre les EPI','Mesurer L1 à la pince côté transformateur','Court-circuiter L1 sur la borne d\'essai, le courant ne doit pas changer','Faire de même pour L2 et L3','Ouvrir le circuit de tension L1, L2, L3, N','Vérifier l\'absence de tension sur le compteur','Changer le compteur'],e:'EPI, pince, court-circuit, L2 L3, ouvrir tension, absence de tension, changer.'},
{t:'vf',q:'La puissance apparente S peut être négative quand l\'énergie est réinjectée.',a:false,e:'Faux. S n\'a jamais de signe. Seules P et Q en ont un.'},
{t:'qcm',q:'Jusqu\'à quel courant environ un compteur est-il en mesure directe ?',c:['20 A','40 A','80 A','200 A'],a:2,e:'Environ 80 A maximum avec fusible en amont.'}]};
/* -------- 8 -------- */
L[8]={t:'Impédance et court-circuit',s:'TN-C, TN-S, TT, IT. Ik min et max. Zs = Ud / Im. 120 s et 100 V.',b:[
{h:'Conception du réseau : les lettres',p:['<b>T</b> = directement mis à la terre. <b>N</b> = neutre. <b>I</b> = isolé ou mis à la terre par impédance. <b>C</b> = PEN combiné. <b>S</b> = N et PE séparés.','<b>IT</b> : neutre isolé ou par impédance (bobine d\'extinction en MT). En BT, avec surveillance d\'isolation, pour continuer à fonctionner sur un premier défaut.','<b>TT</b> : terre du transformateur et terre de l\'installation séparées. Considéré comme <b>obsolète</b>.','<b>TN-C</b> : PEN mis à la terre <b>plusieurs fois</b>. <b>TN-S</b> : PEN mis à la terre à un point puis séparé. Le PE est passif, le N est actif.'],k:'Une fois passé de TN-C à TN-S, on ne réalimente <b>jamais</b> un TN-C en aval.',fig:F.circuit('tn')},
{h:'Ik max et Ik min',p:['<b>Ik maximal</b> : au <b>début</b> du circuit, juste après la protection. Le tripolaire est le plus grand. Il détermine le <b>pouvoir de coupure</b>, les fixations et les sections minimales. Mesuré entre L et L.','<b>Ik minimal</b> : au <b>bout</b> de la ligne, entre L et PEN (unipolaire). Il détermine le <b>coupe-surintensité maximal admissible</b> en amont.','Règle BT : la protection doit couper le Ik minimal en <b>120 secondes</b>, et la tension de contact ne doit pas dépasser <b>100 V CA</b> (240 V CC).'],k:'Ik1 unipolaire ≈ 50 % de Ik3. Ik2 bipolaire ≈ 86 % de Ik3.'},
{h:'Mesurer l\'impédance de boucle',p:['On charge brièvement le réseau avec une résistance connue (5 à 10 ms, pour ne pas faire réagir la protection). Le voltmètre mesure la différence entre réseau chargé et non chargé.','<b>Zs = Ud / Im</b> puis <b>Ik = Un / Zs</b>.','Testeurs d\'installation : 10 à 15 A. Appareils réseau : jusqu\'à 1000 A, courant de mesure max <b>5 × In</b> du fusible amont, dix mesures moyennées.','Erreurs admises : jusqu\'à <b>±30 %</b> selon NIBT, ±10 % courant, ±3 % pour les meilleurs. Sources : fluctuations du réseau, changement de point d\'alimentation, appareil inadapté, pinces oxydées.'],lab:'ik'},
{h:'Calcul et puissance de court-circuit',p:['Un testeur bipolaire mesure la boucle aller et retour : <b>ZkV = ZskV / 2</b>.','Puissance de court-circuit tripolaire : <b>Skv3 = Un² / ZkV</b>. Unipolaire : Skv1 = Un × Ik1 / √3.','Pour dimensionner les protections avec Ik unipolaire, utiliser les résistances à <b>70 °C</b>.','Chute de tension : <b>Ua = Iv × (Z1 + Z2 + ZT)</b>.'],k:'Plus la puissance de court-circuit est élevée, moins le réseau est sensible aux perturbations.'}],
q:[
{t:'num',q:'Testeur : Ud = 2,3 V pour un courant de mesure Im = 10 A. Impédance de boucle Zs en ohms ?',a:0.23,tol:2,u:'Ω',e:'Zs = Ud / Im = 2,3 / 10 = 0,23 Ω.'},
{t:'num',q:'Zs = 0,23 Ω, Un = 230 V. Courant de court-circuit Ik en ampères ?',a:1000,tol:1,u:'A',e:'Ik = 230 / 0,23 = 1000 A.'},
{t:'qcm',q:'Où mesure-t-on le courant de court-circuit minimal ?',c:['Au début de la ligne entre L et L','Au bout de la ligne entre L et PEN','À la station entre L et N','Sur le secondaire du TI'],a:1,e:'Au bout du tronçon à protéger, entre L et PEN.'},
{t:'qcm',q:'Dans un réseau TN-S, le conducteur qui ne conduit du courant qu\'en cas de défaut est…',c:['N','PEN','PE','L3'],a:2,e:'Le PE est passif. Le N est actif, à considérer comme une phase.'},
{t:'qcm',q:'Temps de coupure maximal pour le courant de court-circuit minimal en BT ?',c:['0,3 s','5 s','120 s','15 min'],a:2,e:'120 secondes, et tension de contact ≤ 100 V CA.'},
{t:'qcm',q:'Ik3 = 8 kA en un point. Ordre de grandeur de Ik1 unipolaire au même point (transfo négligé) ?',c:['8 kA','6,9 kA','4 kA','2 kA'],a:2,e:'Ik1 ≈ 50 % de Ik3 = 4 kA. Ik2 ≈ 86 % = 6,9 kA.'},
{t:'vf',q:'Après avoir séparé un réseau TN-C en TN-S, on peut réalimenter un tronçon TN-C en aval si c\'est plus pratique.',a:false,e:'Faux, en aucun cas.'},
{t:'qcm',q:'Erreur de mesure admissible sur l\'impédance de boucle selon la NIBT ?',c:['±3 %','±10 %','±30 %','±50 %'],a:2,e:'Jusqu\'à ±30 %. ±10 % est courant, ±3 % pour les meilleurs.'},
{t:'match',q:'Associe chaque lettre à sa signification.',p:[['T','Directement mis à la terre'],['I','Isolé ou par impédance'],['C','PEN combiné'],['S','N et PE séparés']],e:'T, N, I, C, S.'},
{t:'qcm',q:'Le courant de court-circuit maximal sert à déterminer…',c:['Le coupe-surintensité maximal en amont','Le pouvoir de coupure et les sections minimales','Le temps de déclenchement du DDR','La résistance d\'isolement'],a:1,e:'Ik max → pouvoir de coupure, fixations, sections. Ik min → coupe-surintensité max.'},
{t:'num',q:'Charge monophasée de 40 A. Z1 + Z2 + ZT = 0,25 Ω. Chute de tension Ua en volts ?',a:10,tol:1,u:'V',e:'Ua = 40 × 0,25 = 10 V.'}]};
/* -------- 9 -------- */
L[9]={t:'Analyse du réseau',s:'EN 50160, harmoniques, THD, flicker, raccordement d\'un analyseur.',b:[
{h:'L\'analyseur de réseau',p:['Il combine : enregistrement continu, mesures P Q S en ligne, énergies Wh VAh varh, oscilloscope (formes d\'onde), signaux de télécommande, analyse des harmoniques.','Représentations : <b>numérique</b> (en ligne), <b>spectrale</b> (harmoniques, fondamentale à gauche), <b>tendance</b> (temps en X), <b>vectorielle</b> (phases et déphasages, fonction en ligne).'],k:'<b>EN 50160</b> définit la qualité de la tension au point de fourniture. Elle n\'est ni un niveau CEM ni une limite d\'émission : ça, c\'est la règle <b>D-A-CH-CZ</b>.'},
{h:'Harmoniques',p:['Les charges non linéaires (alimentations, ballasts, variateurs) tirent des courants non sinusoïdaux qui déforment la tension.','<b>Harmonique</b> : multiple entier de 50 Hz (3e = 150 Hz, 5e = 250 Hz). <b>Interharmonique</b> : pas un multiple entier. Décomposition par <b>analyse de Fourier</b>.','<b>THDu</b> : taux d\'harmoniques de tension. <b>THDi</b> : du courant.','Rang et signe : + (fondamentale, 4e, 7e) tourne en avant et échauffe. − (2e, 5e, 8e) tourne en arrière, problèmes de moteur. 0 (<b>3e, 6e, 9e</b>) : <b>s\'additionnent dans le neutre</b>.'],lab:'harm'},
{h:'Valeurs limites',p:['Tension : <b>95 %</b> des moyennes sur 10 min de chaque semaine dans <b>Un ± 10 %</b>, et <b>toutes</b> dans <b>+10 % / −15 %</b>.','Fréquence : 49,5 à 50,5 Hz pendant 95 % du temps, 47 à 52 Hz à 100 %.','<b>THDu = 8 %</b> (niveau de compatibilité). Aucun niveau défini pour le THDi.','Déséquilibre : 2 %, jusqu\'à 3 % en cas particulier. Perturbations étudiées de 0 à environ 10 kHz.','<b>Flicker</b> : impression de scintillement. <b>Pst</b> (short) pour les produits, <b>Plt</b> (long) pour la qualité de tension, Plt < 1.'],k:'Plus la puissance de court-circuit est élevée, moins le réseau est sensible aux perturbations.'},
{h:'Installer un analyseur',p:['Raccorder <b>hors tension</b>. Prises de tension installées après les sondes de courant. Prévoir une batterie si les interruptions comptent.','Raccorder dans l\'ordre PE, N, L1, L2, L3, sondes de courant <b>dans le sens du courant</b>.','En mode en ligne, vérifier : <b>sens de l\'énergie, ordre de phase, rapports de transformation</b>, jeu de paramètres, date, heure, début d\'enregistrement. Étiqueter la mesure.','Choix de l\'appareil : la plupart sont CAT III, TRMS, 1, 3 ou 4 circuits, mémoire, fréquence d\'échantillonnage.']}],
q:[
{t:'qcm',q:'Niveau de compatibilité du THDu en BT ?',c:['3 %','5 %','8 %','10 %'],a:2,e:'THDu = 8 %. Pas de niveau pour le THDi.'},
{t:'qcm',q:'Quels harmoniques s\'additionnent dans le conducteur neutre ?',c:['2e, 4e, 6e','3e, 6e, 9e','5e, 7e, 11e','Tous'],a:1,e:'Les multiples de 3 (signe 0) sont presque en phase et s\'additionnent dans le N.'},
{t:'num',q:'Fréquence du 5e harmonique en hertz ?',a:250,tol:0,u:'Hz',e:'5 × 50 = 250 Hz.'},
{t:'qcm',q:'Dans quelle plage doivent se trouver 95 % des moyennes sur 10 min de la tension ?',c:['Un ± 5 %','Un ± 10 %','Un +10 % / −15 %','Un ± 15 %'],a:1,e:'95 % dans ± 10 %. 100 % dans +10 / −15 %.'},
{t:'qcm',q:'La norme EN 50160 définit…',c:['Les limites d\'émission des consommateurs','La qualité de la tension au point de fourniture','Les niveaux CEM','La sécurité des appareils de mesure'],a:1,e:'Qualité de la tension. Les émissions sont dans D-A-CH-CZ.'},
{t:'qcm',q:'Pst et Plt qualifient…',c:['Le déséquilibre','La fréquence','L\'effet flicker','Les interharmoniques'],a:2,e:'Flicker court terme (produits) et long terme (qualité de tension).'},
{t:'qcm',q:'Un harmonique de signe − (2e, 5e, 8e) provoque…',c:['Une addition dans le neutre','Un champ tournant en arrière et des problèmes de moteur','Rien','Un flicker'],a:1,e:'Sens de rotation en arrière, échauffement et problèmes de moteur.'},
{t:'vf',q:'Le diagramme vectoriel d\'un analyseur sert principalement à évaluer des enregistrements de longue durée.',a:false,e:'Faux. C\'est une fonction en ligne pour voir phases et déphasages à l\'instant T. La tendance sert aux enregistrements.'},
{t:'order',q:'Vérifications en mode en ligne après raccordement : ordre logique du cours.',i:['Sens de l\'énergie','Ordre de phase','Rapports de transformation','Jeu de paramètres, date et heure','Début d\'enregistrement'],e:'Sens de l\'énergie, ordre de phase, rapports, paramètres, puis lancer l\'enregistrement.'},
{t:'qcm',q:'Une oscillation à 175 Hz sur un réseau 50 Hz est…',c:['Un harmonique','Un interharmonique','Un flicker','Une tension de signal'],a:1,e:'175 / 50 = 3,5 : pas un multiple entier, donc interharmonique.'}]};
/* -------- 10 -------- */
L[10]={t:'Résistance et isolement',s:'Pont, montages amont et aval, valeurs NIBT, essais de câbles, tan δ, DP.',b:[
{h:'Mesurer une résistance',p:['<b>Pont de Wheatstone</b> : on règle R3 jusqu\'à annuler le courant dans la diagonale. Alors <b>Rx / R2 = R3 / R4</b>. Pour les petites résistances précises.','<b>Montage amont</b> : l\'ampèremètre est juste, le voltmètre lit trop (chute dans l\'ampèremètre). Résultat trop élevé. Convient aux <b>grandes résistances (> 1 kΩ)</b>.','<b>Montage aval</b> : le voltmètre est juste, l\'ampèremètre lit trop (courant du voltmètre). Résultat trop faible. Convient aux <b>petites résistances (< 1 kΩ)</b>.','<b>Courant stabilisé</b> : on injecte Io connu, on mesure Ux, Rx = Ux / Io. C\'est la méthode des multimètres.'],fig:F.circuit('bridge')},
{h:'Mesure d\'isolement : les valeurs NIBT',p:['Un ohmmètre ne suffit pas : il faut une tension d\'essai élevée et un courant d\'au moins <b>1 mA</b>, en <b>courant continu</b> pour éliminer l\'effet de la capacité du câble.','Installations neuves (après 2010) : <b>SELV/PELV : 250 V, 0,5 MΩ</b>. <b>50 à 500 V : 500 V, 1,0 MΩ</b>. <b>> 500 V : 1000 V, 1,0 MΩ</b>. Avec parafoudre : 250 V, 1,0 MΩ.','Installations d\'avant 1995 : 500 V, 0,25 MΩ (≤ 300 V), 0,05 MΩ en milieu humide.','Câbles BT neufs sortie d\'usine : 500 V CC, <b>> 50 MΩ</b>, plus essai de tension 3,5 kV CA pendant 5 min.'],k:'Mesure toujours <b>hors tension</b>, L et N séparés. Le PE ou PEN peut rester raccordé. Inexactitude admise : <b>30 %</b> (EN 61557).'},
{h:'Procédure sur un câble',p:['1. Informer les clients. 2. Mettre hors tension (le PEN ne doit pas être enlevé). 3. Séparer les conducteurs polaires de tous côtés. 4. Test de fonctionnement de l\'appareil. 5. Mesurer : <b>d\'abord à 1000 V</b>, puis 500 ou 250 si faible. Si ≈ 0 Ω, passer en ohmmètre. Noter L1 PEN, L2 PEN, L3 PEN, L1 L2, L1 L3, L2 L3. 6. Évaluer. 7. Remettre en état. 8. Réenclencher.','Câbles longs : attendre la fin de la <b>charge capacitive</b> avant de lire. Séparer les parafoudres, sinon mesurer à tension plus faible.'],k:'Facteurs d\'influence : matériau, longueur, courant, tension, vieillissement, humidité, encrassement.'},
{h:'Essais et diagnostic des câbles MT',p:['Essai de tension MT : <b>VLF 0,1 Hz à 3 × U0 pendant 30 ou 60 min</b>, ou 2 × U0 à 50 Hz. 85 % des perforations arrivent dans les 30 premières minutes. Câble neuf : U0 de la fiche technique. Câble existant : U0 d\'exploitation.','<b>Essai de gaine</b> : DC polarité négative, <b>5 kV pour PE</b>, <b>3 kV pour PVC</b>, 1 à 5 min.','<b>Tangente delta (tan δ)</b> : facteur de perte, indique <b>humidité et vieillissement</b>. Paliers 0,5, 1,0, 1,5, 2,0 × U0 à 0,1 Hz. Évaluation selon IEEE 400.2.','<b>Décharges partielles (DP)</b> : mesurées en <b>coulombs (pC)</b>. Montrent les points faibles des jonctions et boîtes d\'extrémité, leur position et leur tension d\'apparition. Étalonnage préalable avec un générateur de DP.']}],
q:[
{t:'qcm',q:'Installation neuve en 230/400 V : tension d\'essai et valeur d\'isolement minimale ?',c:['250 V, 0,5 MΩ','500 V, 1,0 MΩ','1000 V, 1,0 MΩ','500 V, 0,25 MΩ'],a:1,e:'Tension nominale 50 à 500 V → 500 V CC, 1,0 MΩ.'},
{t:'qcm',q:'Pour mesurer une résistance de 5 Ω avec un voltmètre et un ampèremètre, quel montage ?',c:['Amont','Aval','Pont de Wheatstone obligatoire','Peu importe'],a:1,e:'Aval pour < 1 kΩ : le courant du voltmètre est négligeable devant celui de Rx.'},
{t:'qcm',q:'Pourquoi la mesure d\'isolement se fait-elle en courant continu ?',c:['Pour économiser la batterie','Pour éliminer l\'influence de la capacité du câble','Parce que l\'ohmmètre est en CC','Pour éviter le flicker'],a:1,e:'En CC, le câble se charge comme un condensateur puis ne laisse passer que le courant de fuite.'},
{t:'qcm',q:'Courant minimal fourni par l\'appareil à la tension d\'essai nominale ?',c:['1 µA','1 mA','10 mA','1 A'],a:1,e:'1 mA minimum.'},
{t:'qcm',q:'Essai de gaine sur un câble isolé PE : tension ?',c:['3 kV DC','5 kV DC négatif','27 kV VLF','500 V DC'],a:1,e:'PE : 5 kV DC polarité négative. PVC : 3 kV.'},
{t:'num',q:'Câble MT dont U0 d\'exploitation vaut 9 kV. Tension de l\'essai VLF à 3 × U0, en kV ?',a:27,tol:1,u:'kV',e:'3 × 9 = 27 kV à 0,1 Hz pendant 30 ou 60 min.'},
{t:'qcm',q:'La tangente delta renseigne surtout sur…',c:['La longueur du câble','L\'humidité et le vieillissement','La position d\'un défaut','La section du conducteur'],a:1,e:'Facteur de perte : humidité et vieillissement de l\'isolant.'},
{t:'qcm',q:'Unité de mesure des décharges partielles ?',c:['Volts','Ampères','Coulombs (pC)','Ohms'],a:2,e:'En coulombs, typiquement des picocoulombs.'},
{t:'order',q:'Procédure de mesure d\'isolement d\'un câble BT.',i:['Informer les clients concernés','Mettre le tronçon hors tension, PEN en place','Séparer les conducteurs polaires de tous les côtés','Tester le fonctionnement de l\'appareil','Mesurer à 1000 V, puis 500 ou 250 V si faible','Évaluer, remettre en état, réenclencher'],e:'Informer, hors tension, séparer, tester l\'appareil, mesurer, évaluer.'},
{t:'vf',q:'Pendant une mesure d\'isolement, le conducteur PE ou PEN doit être déconnecté.',a:false,e:'Faux. Seuls L et N sont séparés. Le PE ou PEN peut rester vissé.'},
{t:'qcm',q:'Pont de Wheatstone : R2 = 100 Ω, R3 = 25 Ω, R4 = 50 Ω à l\'équilibre. Rx ?',c:['12,5 Ω','50 Ω','200 Ω','25 Ω'],a:1,e:'Rx = R2 × R3 / R4 = 100 × 25 / 50 = 50 Ω.'},
{t:'qcm',q:'Inexactitude admise pour un appareil de mesure d\'isolement selon EN 61557 ?',c:['3 %','10 %','30 %','50 %'],a:2,e:'30 %.'}]};
/* -------- 11 -------- */
L[11]={t:'Disjoncteurs différentiels',s:'DDR, RCD : principe du tore, exigences, types AC, A, B, contrôle.',b:[
{h:'Principe',p:['Tous les conducteurs actifs (L et N) traversent un <b>tore</b>. Sans défaut, la somme des courants entrants égale la somme des courants sortants : les champs s\'annulent, rien n\'est induit.','En cas de défaut d\'isolement, une partie du courant retourne par le PE ou par une personne. Le déséquilibre induit une tension dans l\'enroulement secondaire, le relais déclenche.'],k:'Un DDR <b>n\'est pas une protection contre les surintensités</b>. Il ne réagit ni au court-circuit ni à la surcharge. On lui adjoint un disjoncteur LS, ou un combiné LS-DDR.',fig:F.circuit('rcd')},
{h:'Exigences et types',p:['Temps de déclenchement <b>≤ 0,3 s</b> (300 ms), y compris pour les sélectifs.','Courant de défaut ≤ <b>50 % de IΔn</b> : pas de déclenchement. > 50 % : déclenchement immédiat.','<b>Type AC</b> : courants de défaut sinusoïdaux, charges conventionnelles.<br><b>Type A</b> : AC + continus pulsés (alimentations, variateurs, ballasts, UPS monophasés).<br><b>Type B</b> : A + continus lisses, AC jusqu\'à 1000 Hz (convertisseurs de fréquence, UPS, <b>installations PV</b>).','<b>Retardé</b> : 30 à 50 ms contre les déclenchements intempestifs (longues lignes). <b>Sélectif</b> : 120 à 500 ms, avec des DDR plus petits en aval.'],k:'Chantiers : DDR obligatoire sur toute l\'installation et sur les prises ≤ 32 A.'},
{h:'Contrôler un DDR',p:['La <b>touche de contrôle</b> simule un défaut. Elle teste <b>uniquement le DDR</b>, pas l\'installation, et ne donne le temps qu\'approximativement. À actionner régulièrement pour maintenir la disponibilité.','Le testeur injecte un courant de défaut (impulsion ou rampe) et chronomètre jusqu\'au déclenchement. Il affiche <b>temps de déclenchement, courant de déclenchement et tension de défaut</b>.','Procédure : informer, raccorder, régler (courant nominal, sélectivité, forme du courant d\'essai), mesurer, interpréter, procès-verbal.']}],
q:[
{t:'qcm',q:'Temps de déclenchement maximal d\'un DDR ?',c:['0,1 s','0,3 s','1 s','5 s'],a:1,e:'≤ 0,3 s, sélectifs compris.'},
{t:'qcm',q:'DDR 30 mA. Un courant de défaut de 12 mA circule. Que se passe-t-il ?',c:['Déclenchement immédiat','Pas de déclenchement (≤ 50 % de IΔn)','Déclenchement après 0,3 s','Le fusible fond'],a:1,e:'12 mA ≤ 15 mA (50 %) : pas de déclenchement.'},
{t:'qcm',q:'Quel type de DDR pour une installation photovoltaïque avec convertisseur ?',c:['Type AC','Type A','Type B','Type S'],a:2,e:'Type B : courants continus lisses, convertisseurs, PV.'},
{t:'vf',q:'Un DDR protège aussi contre les courts-circuits.',a:false,e:'Faux. Il ne réagit ni au court-circuit ni à la surcharge : il faut un disjoncteur LS.'},
{t:'qcm',q:'La touche de contrôle du DDR vérifie…',c:['L\'installation complète','Uniquement le DDR lui-même','La résistance de terre','Le temps de déclenchement exact'],a:1,e:'Seulement le DDR, avec un temps approximatif.'},
{t:'qcm',q:'Temporisation d\'un DDR sélectif ?',c:['10 ms','30 à 50 ms','120 à 500 ms','1 à 2 s'],a:2,e:'Sélectif : 120 à 500 ms. Retardé : 30 à 50 ms.'},
{t:'match',q:'Associe chaque type de DDR à son application.',p:[['Type AC','Charges conventionnelles, défaut sinusoïdal'],['Type A','Variateurs, ballasts, alimentations monophasées'],['Type B','Convertisseurs de fréquence, UPS, PV']],e:'AC : sinus. A : + pulsé. B : + lisse.'},
{t:'qcm',q:'Quelles valeurs affiche un testeur DDR après mesure ?',c:['Impédance et Ik','Temps de déclenchement, courant de déclenchement, tension de défaut','Isolement et tension d\'essai','THD et cos φ'],a:1,e:'Temps, courant et tension de défaut.'}]};
/* -------- 12 -------- */
L[12]={t:'Défaut de câble',s:'Pré-localisation, localisation précise, et la préparation qui fait tout.',b:[
{h:'Causes et types',p:['Causes : défaut de fabrication, transport et stockage (humidité), pose à <b>moins de 5 °C</b>, erreur de montage, dommage mécanique (fouilles, coup de pioche), surcharge, vieillissement (câbles PPb).','BT : défaut monophasé à la terre, biphasé, triphasé, coupure (y compris PEN).','MT : défaut à la terre (effet selon régime de neutre), défaut double, triphasé, coupure, défaut de gaine.'],k:'Bonne connaissance du réseau et documentation : indispensables. Environ deux ans de pratique pour être efficace.'},
{h:'Pré-localisation (approximative)',p:['<b>Mesures d\'isolement</b> : donnent seulement un aperçu de la nature du défaut. Une coupure à haute impédance n\'apparaît pas.','<b>Réflectométrie</b> : impulsions HF (100 kHz à 50 MHz), réflexions aux jonctions, défauts et extrémités. Vitesse × temps = distance. Pour les défauts <b>basse impédance</b>, les coupures et la fin de câble. Compliqué en BT à cause des dérivations.','<b>Choc avec arc (réflexion sur l\'arc)</b> : courbe de référence sans choc, puis arc au défaut par générateur de choc, nouvelle courbe. Le défaut est à la <b>séparation des deux courbes</b>. Pour les défauts <b>haute impédance (> 300 Ω)</b>. Évite de brûler le défaut.','<b>Impulsion de courant / oscillation</b> : temps de propagation de l\'onde après claquage. Erreur ≈ 5 %.'],fig:F.circuit('tdr')},
{h:'Localisation précise',p:['<b>Fréquence audible</b> (20 à 20 000 Hz) : courant injecté, bobine d\'exploration, casque. Le champ est perturbé au défaut de <b>basse impédance</b>.','<b>Champ hélicoïdal</b> : le pas du câble torsadé crée un champ régulier qui <b>disparaît au point de défaut</b>. Entre phases (L1 L2 = 0 Ω) : pas de défaut à la terre. Phase terre (L3 PEN = 0 Ω) : écran déconnecté et isolé, pont de court-circuit, une phase saine.','<b>Tension de choc</b> (acoustique et magnétique) : claquage 10 à 15 fois par minute, microphone de sol. Le délai entre champ magnétique (3 × 10⁸ m/s) et son (330 m/s) situe le défaut. Pas pour les très faibles impédances (pas de claquage). Attention aux tubes qui font caisse de résonance.']},
{h:'Préparer la localisation',p:['Réunir les données du câble : type, blindage et son traitement, diélectrique, conducteur, longueur, manchons, chambres.','<b>Séparer tous les consommateurs</b> : sinon la mesure d\'isolement ne voit que le parallèle défaut + consommateurs, la réflectométrie est impossible, l\'impulsion de choc <b>détruit l\'électronique</b> des clients, les <b>parafoudres absorbent l\'impulsion</b>, les TI et TP reliés galvaniquement sont endommagés. Court-circuiter les indicateurs de tension capacitifs.','<b>Sectionneur de neutre</b> : l\'ouvrir dans le doute. On peut le laisser fermé si le bâtiment a une électrode de terre de fondations. Ne pas oublier de le refermer.'],k:'Prévoir à l\'avance une procédure d\'accès aux coffrets (serrurier, police) : c\'est la cause n° 1 des retards.'}],
q:[
{t:'qcm',q:'Méthode de pré-localisation adaptée à un défaut à haute impédance (> 300 Ω) ?',c:['Réflectométrie simple','Choc avec arc, réflexion sur l\'arc','Fréquence audible','Mesure d\'isolement'],a:1,e:'La réflexion sur l\'arc rend le défaut basse impédance pendant le choc.'},
{t:'qcm',q:'Dans la méthode de réflexion sur l\'arc, où est le défaut ?',c:['Au premier pic','À la séparation des deux courbes','À la fin de la courbe verte','Au milieu du câble'],a:1,e:'Là où la courbe sans choc et la courbe avec arc divergent.'},
{t:'qcm',q:'La méthode à tension de choc ne fonctionne pas pour…',c:['Les défauts très haute impédance','Les défauts de très faible impédance','Les câbles PE','Les câbles MT'],a:1,e:'Sans claquage, pas de bruit ni d\'impulsion.'},
{t:'qcm',q:'Pourquoi le délai entre le champ magnétique et le son permet-il de situer le défaut ?',c:['Le son voyage plus vite','Le champ est quasi instantané (3 × 10⁸ m/s), le son à 330 m/s','Le champ est absorbé','Le microphone est calibré'],a:1,e:'Le délai est minimal juste au-dessus du défaut.'},
{t:'qcm',q:'Pourquoi séparer les parafoudres avant une localisation par choc ?',c:['Ils s\'échauffent','Ils absorbent l\'impulsion nécessaire','Ils déclenchent le DDR','Ils changent la vitesse de propagation'],a:1,e:'Le parafoudre dérive toute tension supérieure à sa tension assignée, impulsion comprise.'},
{t:'qcm',q:'Champ hélicoïdal pour un défaut L3 à PEN : condition indispensable ?',c:['Toutes les phases en défaut','Écran déconnecté et isolé, une phase saine','Câble sous tension','Réseau TT'],a:1,e:'L\'écran doit être déconnecté et isolé, et il faut une phase saine pour le pont.'},
{t:'vf',q:'Le sectionneur de neutre peut rester fermé si le bâtiment dispose d\'une électrode de terre de fondations.',a:true,e:'Vrai. Sinon il est conseillé de l\'ouvrir. Et de le refermer ensuite.'},
{t:'qcm',q:'Plage de fréquence des impulsions de réflectométrie ?',c:['20 Hz à 20 kHz','500 Hz à 150 kHz','100 kHz à 50 MHz','1 à 10 GHz'],a:2,e:'100 kHz à 50 MHz. 20 Hz à 20 kHz, c\'est la fréquence audible.'},
{t:'qcm',q:'Température de pose minimale des câbles pour éviter un défaut ?',c:['−10 °C','0 °C','5 °C','15 °C'],a:2,e:'Pose en dessous de 5 °C = cause de défaut.'},
{t:'order',q:'Enchaînement logique d\'une localisation de défaut.',i:['Réunir les données du câble et les plans','Séparer tous les consommateurs et parafoudres','Mesure d\'isolement pour caractériser le défaut','Pré-localisation (réflectométrie ou arc)','Localisation précise sur le terrain','Réparer, refermer les sectionneurs de neutre'],e:'Préparer, séparer, caractériser, pré-localiser, localiser, réparer.'}]};
/* -------- 13 -------- */
L[13]={t:'Tracé et identification',s:'Recherche active ou passive, couplages, minimum et maximum, profondeur, géoradar.',b:[
{h:'Actif ou passif',p:['<b>Méthode active</b> : le générateur injecte un courant à une fréquence donnée (500 Hz à 150 kHz, 3 niveaux jusqu\'à 10 à 50 W). Aucune ligne ne se localise sans courant à la fréquence du détecteur.','<b>Méthode passive</b> : on capte ce qui existe déjà. Le <b>50 Hz</b> (il faut une charge minimale : allumer l\'éclairage public) ou les <b>RF</b> 14 à 22 kHz (VLF des émetteurs de radionavigation, couplés aux lignes métalliques).'],k:'Toujours commencer par la <b>puissance la plus faible et la fréquence la plus basse</b>, puis augmenter. Plus c\'est fort et haut, plus les lignes parallèles se couplent aussi.'},
{h:'Types de couplage',p:['<b>Galvanique</b> : générateur relié directement au conducteur. La <b>plus efficace</b>. Ligne coupée et hors tension. Retour par le réseau de terre, ou mieux par un fil auxiliaire éloigné.','<b>Inductif avec pince</b> : sur câble en service. Induit un courant qui passe par le PEN et revient par la terre. Relativement précis si peu de lignes parallèles.','<b>Inductif avec antenne cadre</b> : émetteur posé à l\'aplomb du câble. La <b>moins précise</b>. Meilleur résultat au milieu du câble.','<b>Émetteur mobile (souris, triton)</b> : vissé sur une aiguille de tirage pour les tubes plastiques. Rayonnement ponctuel, on travaille à deux, ligne en T à quatre points. Très précis.']},
{h:'Localiser et mesurer la profondeur',p:['Bobine <b>verticale</b> : <b>minimum</b> de signal au-dessus du câble. Bobine <b>horizontale</b> : <b>maximum</b>. Les appareils récents combinent les deux et guident avec des flèches.','Pivoter lentement à gauche et à droite limite les erreurs de guidage.','<b>Profondeur</b> : minimum à la verticale (A), puis bobine inclinée à <b>45°</b> déplacée latéralement jusqu\'au second minimum (B). La distance x1 = profondeur. Mesurer des deux côtés et moyenner. Si x1 et x2 divergent, un champ perturbe.'],fig:F.circuit('depth')},
{h:'Identifier un câble et le géoradar',p:['On injecte un <b>courant pulsé polarisé</b> dans le câble, boucle fermée par la mise à terre de l\'autre extrémité. Une pince indique l\'amplitude et le sens. Le bon câble donne une indication <b>positive et de plus forte amplitude</b>. Il faut connaître la direction du générateur pour orienter la pince. Toujours couper avec une <b>pince de sécurité</b>.','MT unipolaire : signal couplé sur 2 phases, autre côté à la terre, câbles accessibles sur 1 m, tubes retirés.','<b>Géoradar (GPR)</b> : la <b>seule méthode</b> qui détecte toutes les lignes, métalliques ou non, en 3D. Impulsion électromagnétique HF réfléchie aux interfaces du sol. Souvent monté sur véhicule avec GPS.']}],
q:[
{t:'qcm',q:'Quel couplage est le plus efficace pour la recherche de tracé ?',c:['Inductif avec antenne cadre','Inductif avec pince','Galvanique','Passif 50 Hz'],a:2,e:'Le galvanique, contact direct avec le conducteur, dispersion minimale.'},
{t:'qcm',q:'Bobine en position verticale au-dessus du câble : on obtient…',c:['Un maximum de signal','Un minimum de signal','Aucun signal','La profondeur'],a:1,e:'Vertical = minimum. Horizontal = maximum.'},
{t:'qcm',q:'Recherche passive à 50 Hz sur un câble d\'éclairage public : condition ?',c:['Le câble doit être hors tension','L\'éclairage doit être allumé (charge minimale)','Il faut un générateur','Il faut une fréquence RF'],a:1,e:'Sans charge, pas de courant, donc pas de champ magnétique.'},
{t:'qcm',q:'Mesure de profondeur : angle de la bobine pour le second minimum ?',c:['30°','45°','60°','90°'],a:1,e:'45°. La distance entre les deux minima donne la profondeur.'},
{t:'qcm',q:'Par quoi commence-t-on en réglant le générateur ?',c:['Puissance maximale, fréquence maximale','Puissance minimale, fréquence minimale','Puissance maximale, fréquence minimale','Peu importe'],a:1,e:'Le plus faible et le plus bas, puis on augmente progressivement.'},
{t:'qcm',q:'Lors de l\'identification, le câble recherché donne une indication…',c:['Négative et faible','Positive et de plus forte amplitude','Nulle','Alternée'],a:1,e:'Positive et plus forte. Les câbles voisins portent des retours négatifs.'},
{t:'qcm',q:'Seule méthode capable de détecter des conduites non métalliques en 3D ?',c:['Couplage inductif','Émetteur souris','Géoradar (GPR)','Réflectométrie'],a:2,e:'Le radar à pénétration de sol.'},
{t:'qcm',q:'Plage de fréquence de la recherche passive en mode RF ?',c:['50 Hz','500 Hz à 150 kHz','14 à 22 kHz','100 kHz à 50 MHz'],a:2,e:'14 à 22 kHz, ondes VLF des émetteurs de radionavigation.'},
{t:'vf',q:'Avec le couplage inductif à antenne cadre, le meilleur résultat s\'obtient au milieu du câble.',a:true,e:'Vrai, valable pour la pince comme pour l\'antenne cadre.'}]};
/* -------- 14 -------- */
L[14]={t:'Boss : éclairage public',s:'Directive ESTI 244 : toutes les mesures du cours réunies sur un candélabre.',b:[
{h:'Les valeurs de consigne (ESTI 244)',p:['<b>Tension de défaut</b> ≤ 100 V CA / 240 V CC (candélabre / rambarde). Alternative : mesure d\'isolement ou mesure de Ik.','<b>Impédance de boucle Zs</b> (L PE, L PEN) : mesurée au <b>point le plus éloigné</b> du circuit, pour vérifier que le Ik déclenche la protection. Coefficient de sécurité <b>0,66</b> (vieillissement, erreur d\'appareil, charge). Mesurer à chaque candélabre pour évaluer le PE.','<b>Résistance interne du réseau</b> (L N) : ≤ ±10 % de l\'impédance de boucle (recommandation).','<b>Conducteur de protection du luminaire</b> ≤ <b>0,5 Ω</b> (10 A, 6 à 12 V, au moins 1 s) selon EN 60598-1.','<b>Isolement</b> : installation totale 1 MΩ. Luminaire <b>2 MΩ à 500 V CC</b>.','<b>DDR</b> : 30 mA ≤ 0,3 s. 300 mA ≤ 0,5 s. Courant de déclenchement 40 à 100 % de IΔn. Touche de contrôle.'],k:'Ce niveau mélange tout : c\'est le boss. Tu as le droit à zéro joker.'}],
q:[
{t:'qcm',q:'Où mesure-t-on l\'impédance de boucle d\'un circuit d\'éclairage public ?',c:['Au premier candélabre','Au point le plus éloigné du circuit','Dans l\'armoire seulement','Au transformateur'],a:1,e:'Au point le plus éloigné, là où Ik est minimal.'},
{t:'num',q:'Coefficient de sécurité à appliquer au courant de défaut calculé (ESTI 244) ?',a:0.66,tol:1,u:'',e:'0,66 : vieillissement, erreur d\'appareil, charge du réseau.'},
{t:'qcm',q:'Résistance maximale du conducteur de protection d\'un luminaire ?',c:['0,1 Ω','0,5 Ω','1 Ω','2 Ω'],a:1,e:'≤ 0,5 Ω, mesurée à 10 A sous 6 à 12 V pendant 1 s.'},
{t:'qcm',q:'Isolement minimal d\'un luminaire ?',c:['0,5 MΩ à 250 V','1 MΩ à 500 V','2 MΩ à 500 V','50 MΩ à 500 V'],a:2,e:'2 MΩ à 500 V CC. L\'installation totale : 1 MΩ.'},
{t:'qcm',q:'DDR 300 mA sur un candélabre : temps de déclenchement maximal ?',c:['0,3 s','0,5 s','1 s','5 s'],a:1,e:'300 mA : ≤ 0,5 s. 30 mA : ≤ 0,3 s.'},
{t:'num',q:'Zs mesuré au dernier candélabre : 1,15 Ω sous 230 V. Ik calculé, puis multiplié par 0,66 : quel courant retenir, en ampères ?',a:132,tol:2,u:'A',e:'Ik = 230 / 1,15 = 200 A. × 0,66 = 132 A.'},
{t:'qcm',q:'Un DDR 30 mA doit déclencher pour un courant de défaut compris entre…',c:['0 et 30 mA','15 et 30 mA (40 à 100 % IΔn selon ESTI, 50 à 100 % selon NIBT)','30 et 60 mA','Plus de 60 mA'],a:1,e:'Courant de déclenchement 40 à 100 % de IΔn. Le cours DDR dit : pas de déclenchement ≤ 50 %.'},
{t:'qcm',q:'Révision : un TRMS est indispensable pour mesurer le courant d\'un…',c:['Chauffage résistif','Luminaire LED avec driver électronique','Moteur à vide','Transformateur à vide'],a:1,e:'Le driver tire un courant non sinusoïdal.'},
{t:'qcm',q:'Révision : tension de contact maximale et temps de coupure dans le réseau BT ?',c:['50 V et 0,3 s','100 V CA et 120 s','230 V et 5 s','400 V et 1 s'],a:1,e:'100 V CA (240 V CC) et coupure en 120 s.'},
{t:'qcm',q:'Révision : dans quel ordre raccorder un analyseur de réseau ?',c:['L1, L2, L3, N, PE','PE, N, L1, L2, L3, puis sondes dans le sens du courant','Sondes d\'abord, puis L1 L2 L3','Peu importe si hors tension'],a:1,e:'PE, N, L1, L2, L3, sondes dans le sens du courant, appareil hors tension.'},
{t:'qcm',q:'Révision : que ne faut-il jamais mettre dans le secondaire d\'un TI ?',c:['Un ampèremètre','Une mise à la terre','Un fusible','Un pont de court-circuit'],a:2,e:'Jamais de fusible. Le secondaire reste toujours fermé.'},
{t:'qcm',q:'Révision : un appareil 12 bits sur 500 V. Plus petit pas ?',c:['0,122 V','0,061 V','1,22 V','0,012 V'],a:0,e:'500 / (4096 − 1) = 0,122 V.'}]};

/* ===================== LABORATOIRES ===================== */
const LAB={
rms:{init:()=>({w:'sin'}),html:s=>`<label>Forme d'onde <select data-k="w"><option value="sin"${s.w=='sin'?' selected':''}>Sinus</option><option value="sq"${s.w=='sq'?' selected':''}>Carré symétrique</option><option value="tri"${s.w=='tri'?' selected':''}>Triangle</option><option value="rect"${s.w=='rect'?' selected':''}>Sinus redressé</option><option value="pulse"${s.w=='pulse'?' selected':''}>Carré pulsé (0 / +1)</option></select><span></span></label>`,
out:s=>{const n=2000;let sum=0,abs=0,sq=0,pk=0;const f=t=>{const p=(t*2)%1;switch(s.w){case'sin':return Math.sin(t*4*Math.PI);case'sq':return p<.5?1:-1;case'tri':return 4*Math.abs(p-.5)-1;case'rect':return Math.abs(Math.sin(t*4*Math.PI));case'pulse':return p<.5?1:0}};for(let i=0;i<n;i++){const v=f(i/n);sum+=v;abs+=Math.abs(v);sq+=v*v;pk=Math.max(pk,Math.abs(v))}const avg=sum/n,red=abs/n,eff=Math.sqrt(sq/n);const r=v=>v.toFixed(3);return F.wave(s.w,{avg,rms:eff})+`<div class="read"><div><small>Crête</small><span>${r(pk)}</span></div><div><small>Moyenne</small><span>${r(avg)}</span></div><div><small>Redressée</small><span>${r(red)}</span></div><div><small>Efficace</small><span>${r(eff)}</span></div><div><small>kf = eff/red</small><span>${red?r(eff/red):'∞'}</span></div><div><small>ks = crête/eff</small><span>${r(pk/eff)}</span></div></div><p style="color:var(--muted);font-size:14px;margin:8px 0 0">Un appareil non RMS afficherait redressée × 1,11 = <b class="mono">${r(red*1.11)}</b>. ${s.w=='sin'?'Juste, car c\'est un sinus.':'Faux : l\'écart avec la vraie valeur efficace est de '+((red*1.11/eff-1)*100).toFixed(0)+' %.'}</p>`}},
quant:{init:()=>({b:8,u:250}),html:s=>`<label>Bits N <input type="range" min="2" max="24" value="${s.b}" data-k="b"><span class="mono">${s.b} bits</span></label><label>Étendue <input type="range" min="10" max="1000" step="10" value="${s.u}" data-k="u"><span class="mono">${s.u} V</span></label>`,
out:s=>{const P=Math.pow(2,s.b),d=s.u/(P-1);return `<div class="read"><div><small>Points 2^N</small><span>${P.toLocaleString('fr-CH')}</span></div><div><small>Plus petit pas Δ</small><span>${d<0.001?(d*1e6).toFixed(2)+' µV':d<1?(d*1000).toFixed(3)+' mV':d.toFixed(3)+' V'}</span></div></div>`}},
ti:{init:()=>({i1:400,i2:5,l:10}),html:s=>`<label>Courant primaire I1 <input type="range" min="50" max="2000" step="50" value="${s.i1}" data-k="i1"><span class="mono">${s.i1} A</span></label><label>Secondaire nominal <select data-k="i2"><option${s.i2==5?' selected':''}>5</option><option${s.i2==1?' selected':''}>1</option></select><span class="mono">${s.i2} A</span></label><label>Longueur ligne 2,5 mm² <input type="range" min="1" max="50" value="${s.l}" data-k="l"><span class="mono">${s.l} m</span></label>`,
out:s=>{const K=s.i1/s.i2,Rb=0.0175*2*s.l/2.5,S=s.i2*s.i2*Rb;return `<div class="read"><div><small>Rapport K</small><span>${K}</span></div><div><small>Rb (aller-retour)</small><span>${Rb.toFixed(3)} Ω</span></div><div><small>Puissance requise</small><span>${S.toFixed(2)} VA</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">À 1 A secondaire, la ligne consomme 25 fois moins qu'à 5 A. C'est pour ça que les longues lignes de mesure préfèrent 1 A.</p>`}},
power:{init:()=>({u:230,i:10,phi:30}),html:s=>`<label>Tension U <input type="range" min="100" max="400" step="10" value="${s.u}" data-k="u"><span class="mono">${s.u} V</span></label><label>Courant I <input type="range" min="1" max="100" value="${s.i}" data-k="i"><span class="mono">${s.i} A</span></label><label>Déphasage φ <input type="range" min="0" max="90" value="${s.phi}" data-k="phi"><span class="mono">${s.phi}°</span></label>`,
out:s=>{const r=s.phi*Math.PI/180,S=s.u*s.i,P=S*Math.cos(r),Q=S*Math.sin(r);const W=300,H=170,sc=120/S;return `<svg viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="#0a0f1a"/><line x1="40" y1="140" x2="${40+P*sc}" y2="140" stroke="#5BD98A" stroke-width="5"/><line x1="${40+P*sc}" y1="140" x2="${40+P*sc}" y2="${140-Q*sc}" stroke="#4FD1E8" stroke-width="5"/><line x1="40" y1="140" x2="${40+P*sc}" y2="${140-Q*sc}" stroke="#FFB347" stroke-width="3"/>${T(40+P*sc/2,158,'P','#5BD98A')}${T(40+P*sc+14,140-Q*sc/2,'Q','#4FD1E8','start')}${T(30+P*sc/2,125-Q*sc/2,'S','#FFB347')}${T(70,150,'φ = '+s.phi+'°','#8A98B4','start')}</svg><div class="read"><div><small>S apparente</small><span>${(S/1000).toFixed(2)} kVA</span></div><div><small>P active</small><span>${(P/1000).toFixed(2)} kW</span></div><div><small>Q réactive</small><span>${(Q/1000).toFixed(2)} kvar</span></div><div><small>cos φ</small><span>${Math.cos(r).toFixed(2)}</span></div></div>`}},
ik:{init:()=>({ud:2.3,im:10}),html:s=>`<label>Tension différentielle Ud <input type="range" min="0.2" max="20" step="0.1" value="${s.ud}" data-k="ud"><span class="mono">${(+s.ud).toFixed(1)} V</span></label><label>Courant de mesure Im <input type="range" min="5" max="1000" step="5" value="${s.im}" data-k="im"><span class="mono">${s.im} A</span></label>`,
out:s=>{const Zs=s.ud/s.im,Ik=230/Zs;return `<div class="read"><div><small>Zs = Ud / Im</small><span>${Zs.toFixed(3)} Ω</span></div><div><small>Ik3 (100 %)</small><span>${Math.round(Ik)} A</span></div><div><small>Ik2 (86 %)</small><span>${Math.round(Ik*.86)} A</span></div><div><small>Ik1 (50 %)</small><span>${Math.round(Ik*.5)} A</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">${Zs<0.05?'<span class="warn">Impédance très faible : un testeur à 10 A verrait une chute de quelques dizaines de millivolts, difficile à interpréter. Il faut un appareil à fort courant de mesure.</span>':'Le courant de mesure ne dure que 5 à 10 ms, pour ne pas faire réagir la protection amont.'}</p>`}},
harm:{init:()=>({h3:0.2,h5:0.1}),html:s=>`<label>3e harmonique (150 Hz) <input type="range" min="0" max="0.6" step="0.05" value="${s.h3}" data-k="h3"><span class="mono">${Math.round(s.h3*100)} %</span></label><label>5e harmonique (250 Hz) <input type="range" min="0" max="0.6" step="0.05" value="${s.h5}" data-k="h5"><span class="mono">${Math.round(s.h5*100)} %</span></label>`,
out:s=>{const thd=Math.sqrt(s.h3*s.h3+s.h5*s.h5)*100;return F.wave('harm',{h3:+s.h3,h5:+s.h5})+`<div class="read"><div><small>THD</small><span>${thd.toFixed(1)} %</span></div><div><small>Limite THDu</small><span>8 %</span></div><div><small>Verdict</small><span style="color:${thd>8?'var(--bad)':'var(--ok)'}">${thd>8?'Dépassé':'Conforme'}</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Le 3e harmonique (signe 0) s'additionne dans le neutre. Le 5e (signe −) tourne en arrière et gêne les moteurs.</p>`}}};

/* ===================== LABOS AJOUTÉS (v2 mondes) ===================== */
const f1=v=>(''+(Math.round(v*100)/100)).replace('.',',').replace('-','−');
LAB.volt={init:()=>({ri:10,r:100}),
html:s=>`<label>Résistance interne Ri du voltmètre <input type="range" min="0.01" max="10" step="0.01" value="${s.ri}" data-k="ri"><span class="mono">${s.ri} MΩ</span></label><label>Résistance mesurée R (diviseur) <input type="range" min="1" max="1000" step="1" value="${s.r}" data-k="r"><span class="mono">${s.r} kΩ</span></label>`,
out:s=>{const R=s.r*1e3,Ri=s.ri*1e6,U=100;const Rp=R*Ri/(R+Ri);const Uv=U*Rp/(R+Rp);const err=(Uv-50)/50*100;return `<div class="read"><div><small>Tension vraie</small><span>50,0 V</span></div><div><small>Tension lue</small><span>${f1(Uv)} V</span></div><div><small>Erreur de charge</small><span class="${Math.abs(err)>1?'warn':''}">${f1(err)} %</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Deux résistances R en série sous 100 V : la vraie tension au milieu vaut 50 V. Le voltmètre se met <b>en parallèle</b> sur une des deux et forme un diviseur avec elle. Plus Ri est grande face à R, moins il « vole » de courant et moins il fausse la lecture. Monte R : l'erreur explose. C'est pour ça qu'un voltmètre doit avoir une Ri énorme.</p>`}};
LAB.shunt={init:()=>({ia:1,ri:0.1,imax:10}),
html:s=>`<label>Calibre de l'ampèremètre Ia <input type="range" min="0.1" max="5" step="0.1" value="${s.ia}" data-k="ia"><span class="mono">${s.ia} A</span></label><label>Résistance interne Ri <input type="range" min="0.01" max="1" step="0.01" value="${s.ri}" data-k="ri"><span class="mono">${s.ri} Ω</span></label><label>Courant à mesurer I max <input type="range" min="1" max="200" step="1" value="${s.imax}" data-k="imax"><span class="mono">${s.imax} A</span></label>`,
out:s=>{const n=s.imax/s.ia;if(n<=1)return `<div class="read"><div><small>Shunt</small><span>inutile</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">I max ne dépasse pas le calibre : pas besoin de shunt.</p>`;const rs=s.ri/(n-1);const is=s.imax-s.ia;return `<div class="read"><div><small>Facteur n</small><span>${f1(n)}</span></div><div><small>Rs = Ri / (n − 1)</small><span>${(rs<0.01?rs.toExponential(2):f1(rs)).replace('.',',')} Ω</span></div><div><small>Courant dans le shunt</small><span>${f1(is)} A</span></div><div><small>Chute U = Ri · Ia</small><span>${f1(s.ri*s.ia*1000)} mV</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Le shunt est <b>en parallèle</b> avec l'ampèremètre. Les deux voient la même tension. Le shunt, bien plus petit que Ri, avale le gros du courant et l'appareil ne reçoit que sa part (Ia). Pour multiplier l'étendue par n, il faut Rs = Ri / (n − 1).</p>`}};
LAB.rcd={init:()=>({idn:30,il:0,il2:0}),
html:s=>`<label>Sensibilité IΔn <select data-k="idn"><option${s.idn==10?' selected':''}>10</option><option${s.idn==30?' selected':''}>30</option><option${s.idn==300?' selected':''}>300</option></select><span class="mono">${s.idn} mA</span></label><label>Courant de fuite à la terre <input type="range" min="0" max="400" step="1" value="${s.il}" data-k="il"><span class="mono">${s.il} mA</span></label>`,
out:s=>{const il=+s.il,idn=+s.idn;const st=il>=idn?'déclenche':il>=idn/2?'peut déclencher':'reste fermé';const c=il>=idn?'warn':il>=idn/2?'':'';return `<div class="read"><div><small>Aller (L)</small><span>10 000 mA</span></div><div><small>Retour (N)</small><span>${10000-il} mA</span></div><div><small>Différence vue par le tore</small><span class="${c}">${il} mA</span></div><div><small>DDR ${idn} mA</small><span class="${c}">${st}</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Le tore additionne les courants aller et retour. Sans fuite, la somme est nulle : rien n'est induit. Une fuite déséquilibre la somme : le tore induit une tension dans la bobine de détection et le relais déclenche. Norme : doit déclencher entre <b>IΔn / 2</b> et <b>IΔn</b> (jamais en dessous de la moitié, toujours à IΔn).</p>`}};
L[5].b[1].lab='volt';L[5].b[2].lab='shunt';L[11].b[0].lab='rcd';
/* Mondes */
const W=[
{n:'Le laboratoire',e:'🔬',c:'#4FD1E8',d:'Vocabulaire, appareils, formes d\'onde. Les fondations.',l:[1,2,3]},
{n:'La cabine',e:'⚡',c:'#FFB347',d:'Phases, ampèremètre, voltmètre, transfos de mesure, compteurs.',l:[4,5,6,7]},
{n:'Le réseau sous tension',e:'🏭',c:'#5BD98A',d:'Boucle de défaut, court-circuit, qualité du réseau.',l:[8,9]},
{n:'Les câbles',e:'🕳️',c:'#C084FC',d:'Isolement, DDR, défauts de câble, tracé.',l:[10,11,12,13]},
{n:'Le candélabre',e:'👑',c:'#FF6B6B',d:'Directive ESTI 244. Toutes les mesures réunies. Boss final.',l:[14]}];

/* ===================== ENRICHISSEMENT PDF (chap. 4 et 7 du support) ===================== */
/* --- Chapitre 5 du jeu : mesurer I et U (support 4.1 à 4.6) --- */
L[5].b.splice(1,0,{h:'L\'ampèremètre fausse le circuit',p:['En se mettant <b>en série</b>, l\'ampèremètre ajoute sa propre résistance Rm au circuit. Le courant qui passe devient donc plus petit que celui qui passait avant qu\'on branche l\'appareil.','Sans appareil : <b>I₁ = U / (Ri + R)</b>. Avec l\'appareil : <b>I₂ = U / (Ri + R + Rm)</b>. La résistance interne d\'un multimètre en ampèremètre vaut entre <b>0,01 et 2 Ω</b>.','Si Rm est très petite devant Ri + R, on néglige l\'erreur. Sinon on corrige : <b>I<sub>corr</sub> = I × (1 + Rm / (Ri + R))</b>.'],k:'Retiens la logique : l\'ampèremètre <b>freine</b> le courant, donc il en lit <b>trop peu</b>. La correction se fait donc toujours <b>vers le haut</b>.'});
L[5].b.push({h:'Étendre l\'étendue en courant',p:['Pour changer de calibre en courant, on commute des <b>résistances en parallèle</b>. Le problème : sur des calibres de quelques ampères ces résistances sont minuscules, et les <b>résistances de contact de l\'interrupteur</b> deviennent du même ordre de grandeur.','Ces résistances de contact ne sont ni contrôlables ni stables dans le temps, donc elles ajoutent une erreur imprévisible. Le cours montre deux montages : celui où le commutateur est placé de façon que <b>la répartition du courant ne dépende pas</b> des résistances de contact est le bon (illustration 36).'],k:'Le bon montage de commutation est celui où <b>les résistances de contact du commutateur ne participent pas</b> à la répartition du courant.'});
L[5].q.push(
{t:'num',q:'L\'ampèremètre affiche 2,00 A. Sa résistance interne Rm = 0,5 Ω, le reste du circuit Ri + R = 100 Ω. Quel est le courant corrigé, en ampères ?',a:2.01,tol:1,u:'A',e:'I_corr = I × (1 + Rm / (Ri + R)) = 2,00 × (1 + 0,5/100) = 2,01 A. L\'appareil lit toujours un peu trop peu, on corrige vers le haut.'},
{t:'qcm',q:'Entre quelles valeurs se situe la résistance interne d\'un multimètre utilisé en ampèremètre, selon le cours ?',c:['0,01 à 2 Ω','2 à 20 Ω','1 à 10 kΩ','plusieurs MΩ'],a:0,e:'0,01 à 2 Ω. Elle doit rester très faible pour ne pas freiner le courant qu\'on veut mesurer.'},
{t:'vf',q:'Un ampèremètre lit toujours un courant légèrement plus faible que celui qui circulait avant qu\'on le branche.',a:true,e:'Vrai. Il ajoute Rm en série, donc I₂ = U/(Ri+R+Rm) est plus petit que I₁ = U/(Ri+R).'},
{t:'num',q:'Shunt de 0,01 Ω. Le voltmètre lit 75 mV à ses bornes. Quel courant traverse le shunt, en ampères ?',a:7.5,tol:1,u:'A',e:'I = Um / Rs = 0,075 / 0,01 = 7,5 A. C\'est tout le principe du shunt : on mesure une tension et on en déduit un courant.'},
{t:'qcm',q:'Quelles valeurs typiques le cours donne-t-il pour un shunt ?',c:['0,01 Ω ou 0,001 Ω','0,1 Ω ou 1 Ω','10 Ω ou 100 Ω','1 kΩ ou 10 kΩ'],a:0,e:'0,01 Ω ou 0,001 Ω. Très faible impédance, pour ne pas perturber le circuit malgré les grandes intensités.'},
{t:'order',q:'Remets dans l\'ordre le raisonnement de la mesure par shunt.',i:['Le courant I à mesurer traverse le shunt Rs','Une chute de tension Um apparaît aux bornes de Rs','Le voltmètre mesure Um','On calcule I = Um / Rs'],e:'Le shunt convertit un courant en tension. C\'est la méthode reine pour les grandes intensités.'},
{t:'qcm',q:'Dans un shunt quatre fils, pourquoi les chutes de tension dans Rk1 et Rk2 ne faussent-elles pas la mesure ?',c:['Parce que les contacts de tension sont séparés des contacts de puissance','Parce que Rk1 et Rk2 sont compensées électroniquement','Parce que le courant de mesure est alternatif','Parce que le shunt est refroidi'],a:0,e:'Les contacts de tension sont séparés des raccordements de puissance. Le circuit de mesure ne voit que Urs, pas les chutes dans les contacts de puissance.'},
{t:'num',q:'Voltmètre de résistance interne Rm = 2 kΩ, pleine déviation à 5 V. Quelle résistance série Rv faut-il pour lire jusqu\'à 50 V, en ohms ?',a:18000,tol:2,u:'Ω',e:'Rv = Rm × (U − Umax) / Umax = 2000 × (50 − 5)/5 = 18 000 Ω, soit 18 kΩ.'},
{t:'vf',q:'Doubler l\'étendue de mesure en tension d\'un voltmètre double aussi sa résistance d\'entrée.',a:true,e:'Vrai. C\'est pour cela que la résistance d\'entrée se note en kΩ/V, rapportée à la déviation maximale.'},
{t:'qcm',q:'Pourquoi le cours dit-il qu\'on peut ignorer en pratique l\'erreur due à la consommation propre du voltmètre ?',c:['Parce que sa résistance interne, de plusieurs kΩ voire MΩ, ne prélève presque aucun courant','Parce que les voltmètres sont étalonnés en usine','Parce que l\'erreur est compensée par le logiciel','Parce que la tension mesurée est toujours faible'],a:0,e:'Sa très grande impédance fait qu\'il détourne un courant négligeable. Dans un circuit à très haute résistance, l\'erreur redevient visible.'},
{t:'qcm',q:'Lors d\'une commutation de calibres en courant, quel montage faut-il préférer ?',c:['Celui où la répartition du courant ne dépend pas des résistances de contact du commutateur','Celui qui utilise le moins de résistances','Celui où le commutateur est en série avec l\'appareil','Celui qui utilise des résistances de forte valeur'],a:0,e:'Les résistances de contact sont instables dans le temps. Le bon montage les met hors du chemin de répartition du courant.'},
{t:'match',q:'Associe chaque mesure de courant du métier à son domaine.',p:[['4 à 20 mA CC','Transducteur vers le système d\'exploitation'],['0 à 1 A CA','Secondaire des transfos de mesure HT/MT'],['0 à 5 A CA','Secondaire des transfos de mesure MT/BT'],['0 à 200 A CC','Charge et décharge des batteries de secours']],e:'Ce sont les cinq familles de mesures de courant listées au début du chapitre 4 du support.'},
{t:'qcm',q:'Sur une mesure directe de courant proche du calibre maximal, quel paramètre le cours demande-t-il de surveiller ?',c:['La durée de mesure maximale autorisée','La température ambiante','La fréquence du réseau','La polarité des cordons'],a:0,e:'Jusqu\'à 20 A en direct, mais la durée de mesure est limitée : le shunt interne chauffe.'});
/* --- Chapitre 8 du jeu : impédance et court-circuit (support 7.1 à 7.10) --- */
L[8].b.splice(3,0,{h:'De la boucle mesurée à l\'impédance du réseau',p:['Un testeur bipolaire mesure toujours une <b>boucle</b> : le courant part par un conducteur et revient par l\'autre. La valeur affichée Z<sub>skV</sub> contient donc <b>l\'aller et le retour</b>.','Pour obtenir l\'impédance du réseau vue en un point, on divise par deux : <b>Z<sub>kV</sub> = Z<sub>skV</sub> / 2</b>.','Vocabulaire à ne pas mélanger : la boucle <b>L – N</b> s\'appelle souvent résistance interne du réseau (Ri), la boucle <b>L – PE</b> s\'appelle impédance de boucle.'],k:'L\'appareil mesure un <b>aller-retour</b>. L\'impédance du réseau en un point, c\'est <b>la moitié</b> de ce qu\'il affiche.'});
L[8].b.push({h:'Comment l\'appareil s\'y prend, concrètement',p:['On ne peut pas mesurer une résistance dans un réseau <b>sous tension</b> avec un ohmmètre. Alors l\'appareil triche : il <b>charge brièvement le réseau</b> avec une résistance connue et regarde de combien la tension s\'effondre.','Il compare la tension du réseau <b>à vide</b> et <b>en charge</b>. La différence, c\'est U<sub>d</sub>. Il connaît le courant qu\'il a tiré, I<sub>m</sub>. Il calcule <b>Z<sub>s</sub> = U<sub>d</sub> / I<sub>m</sub></b>, puis <b>I<sub>k</sub> = U<sub>n</sub> / Z<sub>s</sub></b>.','La charge ne dure que <b>5 à 10 ms</b> pour ne pas faire réagir les coupe-surintensité en amont. Les testeurs d\'installation tirent 10 à 15 A, les appareils de réseau jusqu\'à 1000 A. Plus le courant de mesure est fort, mieux on voit les mauvais contacts.'],k:'Un courant de mesure <b>faible</b> ne révèle pas les bornes mal serrées, et sur une impédance faible il ne crée presque aucune chute de tension. Voilà pourquoi les vrais appareils de réseau tirent fort.'});
L[8].q.push(
{t:'num',q:'Un testeur relève une tension différentielle Ud = 1,8 V pour un courant de mesure Im = 12 A. Quelle est l\'impédance de boucle Zs, en ohms ?',a:0.15,tol:2,u:'Ω',e:'Zs = Ud / Im = 1,8 / 12 = 0,15 Ω.'},
{t:'num',q:'Le testeur affiche une impédance de boucle Zs = 0,24 Ω. Quelle est l\'impédance du réseau ZkV en ce point, en ohms ?',a:0.12,tol:2,u:'Ω',e:'ZkV = ZskV / 2 = 0,12 Ω. L\'appareil bipolaire mesure toujours l\'aller et le retour.'},
{t:'num',q:'ZkV = 0,08 Ω sous une tension composée de 400 V. Quelle est la puissance de court-circuit tripolaire, en kVA ?',a:2000,tol:3,u:'kVA',e:'Skv3 = Un² / ZkV = 400² / 0,08 = 2 000 000 VA = 2000 kVA, soit 2 MVA.'},
{t:'num',q:'Ik3 tripolaire = 6000 A en un point. Quel est l\'ordre de grandeur de Ik1 unipolaire au même point ?',a:3000,tol:5,u:'A',e:'Ik1 unipolaire vaut environ 50 % de Ik3. Ik2 biphasé en vaut environ 86 %.'},
{t:'num',q:'Ik3 tripolaire = 10 kA. Quel est le courant de court-circuit biphasé Ik2, en kA ?',a:8.6,tol:4,u:'kA',e:'Ik2 biphasé ≈ 86 % de Ik3, soit 8,6 kA.'},
{t:'num',q:'Impédance du conducteur polaire ZL = 0,10 Ω, tension entre phase et PEN 230 V, transformateur et mise au neutre négligés. Ik1 monophasé, en ampères ?',a:1150,tol:3,u:'A',e:'Ik1 = Ustr / (2 × ZL) = 230 / 0,2 = 1150 A. Le facteur 2 vient de l\'aller-retour, puisque ZPEN est pris égal à ZL.'},
{t:'num',q:'Charge monophasée de 63 A. Z1 + Z2 + ZT = 0,12 Ω. Quelle est la chute de tension Ua, en volts ?',a:7.56,tol:3,u:'V',e:'Ua = Iv × (Z1 + Z2 + ZT) = 63 × 0,12 = 7,56 V.'},
{t:'num',q:'Fusible amont de 25 A. Quel courant de mesure maximal choisit-on pour ne pas le faire déclencher ?',a:125,tol:1,u:'A',e:'Maximum 5 × In, soit 125 A. Au-delà, on risque de couper le tronçon en le mesurant.'},
{t:'qcm',q:'Combien de temps l\'appareil applique-t-il sa charge pour mesurer l\'impédance ?',c:['5 à 10 millisecondes','5 à 10 secondes','1 à 2 secondes','120 secondes'],a:0,e:'5 à 10 ms. Assez pour voir la chute de tension, trop court pour réveiller les coupe-surintensité en amont.'},
{t:'qcm',q:'Pourquoi un courant de mesure faible est-il un problème ?',c:['Il ne révèle pas les résistances de contact et crée une chute de tension trop petite à interpréter','Il chauffe trop la résistance de test','Il fait déclencher les différentiels','Il fausse la fréquence mesurée'],a:0,e:'Sur une impédance faible ou une borne mal serrée, un petit courant ne fait presque rien apparaître. Les appareils de réseau chargent jusqu\'à 1000 A.'},
{t:'qcm',q:'Quel courant de charge un testeur d\'installation courant applique-t-il ?',c:['10 à 15 A','1 à 2 A','50 à 100 A','environ 1000 A'],a:0,e:'10 à 15 A pour un testeur d\'installation. Jusqu\'à 1000 A pour les appareils spécialisés réseau.'},
{t:'order',q:'Remets dans l\'ordre la mesure d\'impédance de boucle.',i:['Mesurer la tension du réseau à vide','Charger brièvement le réseau avec une résistance connue','Mesurer la tension du réseau en charge','Calculer Zs = Ud / Im','En déduire Ik = Un / Zs'],e:'On ne mesure jamais directement une impédance sous tension : on provoque une chute de tension et on la divise par le courant tiré.'},
{t:'match',q:'Associe chaque boucle mesurée à son appellation ou à son usage.',p:[['Boucle L – N','Résistance interne du réseau (Ri)'],['Boucle L – PE','Impédance de boucle'],['Boucle L – PEN en bout de ligne','Courant de court-circuit minimal'],['Boucle L – L','Courant de court-circuit maximal']],e:'Savoir quelle boucle a été mesurée est indispensable pour interpréter la valeur affichée.'},
{t:'qcm',q:'À quoi sert la sonde S enfichée dans un secteur non influencé lors de la mesure ?',c:['À déterminer la tension de défaut Uf','À alimenter l\'appareil de mesure','À vérifier le sens de rotation des phases','À mesurer la résistance de terre du transformateur'],a:0,e:'Elle donne le potentiel de référence non influencé, ce qui permet de mesurer la tension de défaut Uf.'},
{t:'num',q:'Hors de la zone d\'influence de la mise à la terre, quelle tension alternative maximale peut apparaître entre le conducteur de protection et le sol, en volts ?',a:100,tol:0,u:'V',e:'100 V en alternatif, et 240 V en continu. La coupure doit se faire en 120 secondes.'},
{t:'qcm',q:'Quel texte fixe les tensions de contact admissibles dans les réseaux BT ?',c:['L\'ordonnance sur les installations à courant fort RS 734.2, article 55','La norme EN 50160','La directive ESTI 244','La NIBT chapitre 6'],a:0,e:'Ordonnance sur les installations à courant fort du 30 mars 1994, chapitre 4 « Mesures de protection », article 55.'},
{t:'vf',q:'Le courant de court-circuit tripolaire est en général plus faible que le bipolaire ou l\'unipolaire.',a:false,e:'Faux, c\'est l\'inverse. Le tripolaire est le plus élevé : il sert de référence à 100 %.'},
{t:'qcm',q:'Où le courant de court-circuit le plus élevé apparaît-il ?',c:['Au début du circuit, juste après le dispositif de protection','Au bout de la ligne','Au point neutre du transformateur','À mi-parcours de la ligne'],a:0,e:'Ik max au début du circuit, Ik min au bout de la ligne. Les deux servent à des dimensionnements différents.'},
{t:'qcm',q:'Sur un mesureur d\'impédance qui répète la mesure dix fois, que fait-il de ces résultats ?',c:['Il en calcule la moyenne pour gagner en exactitude','Il retient la valeur la plus élevée','Il retient la valeur la plus faible','Il les affiche toutes séparément'],a:0,e:'Plusieurs mesures moyennées réduisent l\'effet des fluctuations de tension du réseau.'},
{t:'qcm',q:'Laquelle de ces situations n\'est pas une source d\'erreur citée par le cours sur la mesure d\'impédance ?',c:['La température ambiante du local','Les fluctuations de tension pendant la mesure','Le changement de point d\'alimentation','Des pinces crocodiles oxydées'],a:0,e:'Le cours cite les fluctuations de tension, le changement de station, un appareil inadapté et les mauvais raccordements. Pas la température du local.'},
{t:'qcm',q:'Pour dimensionner les appareils de protection à partir du courant de court-circuit unipolaire, à quelle température prend-on les résistances ?',c:['70 °C','20 °C','0 °C','90 °C'],a:0,e:'À 70 °C. Le conducteur chaud résiste davantage, donc Ik est plus faible : c\'est le cas défavorable.'},
{t:'qcm',q:'Une mesure de courant de court-circuit dans le réseau de distribution fait chuter la valeur instantanée de la tension de 317 V à 200 V. Qu\'est-ce que cela indique ?',c:['Une impédance de réseau notable en ce point','Un défaut d\'isolement','Une erreur de raccordement de l\'appareil','Une fréquence anormale'],a:0,e:'Plus le creux de tension est marqué pour un même courant de mesure, plus l\'impédance du réseau est élevée. Dans une station transformatrice, on n\'observe presque aucune variation.'});
L[6].q.push({t:'vf',q:'Des fusibles sont admis dans le circuit secondaire d\'un transformateur d\'intensité.',a:false,e:'Faux. C\'est le même piège que l\'ouverture du secondaire : un fusible qui fond ouvre le circuit, le noyau sature et des tensions dangereuses apparaissent.'},
{t:'qcm',q:'Que faut-il faire des noyaux non utilisés d\'un transformateur de mesure à plusieurs noyaux ?',c:['Les mettre en court-circuit','Les laisser ouverts','Les relier à la terre par une résistance','Les charger avec la puissance nominale'],a:0,e:'Comme tout secondaire de transformateur d\'intensité : en court-circuit, jamais ouvert.'},
{t:'qcm',q:'Que se passe-t-il si la résistance de charge au secondaire d\'un transformateur d\'intensité est trop élevée ?',c:['Le noyau sature avant même d\'atteindre le courant nominal','Le rapport de transformation double','Le secondaire chauffe puis fond','Rien, c\'est le cas favorable'],a:0,e:'Charge trop élevée : saturation prématurée. Charge trop faible : inexactitudes. La puissance du transformateur doit être adaptée à l\'installation.'},
{t:'vf',q:'Les transformateurs de mesure destinés aux mesures de décompte doivent être vérifiés officiellement une seule fois et marqués en conséquence.',a:true,e:'Vrai. Vérification officielle unique, puis marquage.'});

